/* Notes photographs data. Kester Small. */
window.COURSE_NOTE_PHOTOS = {"M1U1":[{"screen":"Recap: the creative design process","src":"img/notes/n_oXqn2CXC_9Q.jpg","w":1000,"h":751,"alt":"Person studying a wall covered in colourful sticky notes during a brainstorming session","cap":"A designer studies a wall of sticky notes gathered while brainstorming ideas. Laying every idea out like this lets a team see the whole creative design process at once, from defining the problem through to choosing ideas to develop.","by":"Per Lööv","title":"Real world:"},{"screen":"The creative process","src":"img/notes/n_eQux_nmDew0.jpg","w":1000,"h":667,"alt":"Paper sketches and coloured markers spread across a desk","cap":"Sketches and markers spread across a desk show ideas being worked out on paper. The creative process moves in stages like this, from loose early thinking towards refined, finished work.","by":"Jason Coudriet","title":"Real world:"},{"screen":"The role of pre-production","src":"img/notes/n_br2HgQuvq6I.jpg","w":1000,"h":667,"alt":"Film crew with camera and lighting equipment working on a studio soundstage","cap":"A film crew works with cameras and lights on a soundstage. A shoot like this only runs smoothly because of pre-production: the scripts, schedules, budgets and equipment lists prepared long before anyone arrives on set.","by":"Brands&People","title":"Real world:"},{"screen":"Problem definition: purpose and goal","src":"img/notes/n_KdeqA3aTnBY.jpg","w":1000,"h":667,"alt":"Group of people sitting around a table with pens and papers in a discussion","cap":"A team sits around a table with pens and notes, talking a project through. Agreeing at the start on the purpose and goal of a product keeps everyone working on the same clearly defined problem.","by":"Dylan Gillis","title":"Real world:"},{"screen":"Target audience and market analysis","src":"img/notes/n_FPt10LXK0cg.jpg","w":1000,"h":667,"alt":"Row of people side by side each holding and scrolling a smartphone","cap":"A row of people each scroll their own smartphone. Market analysis asks who these viewers are, which devices and platforms they use and what they want, so that a product is designed for its real target audience.","by":"ROBIN WORRALL","title":"Real world:"},{"screen":"Brainstorming: mind mapping, SCAMPER and rapid ideation","src":"img/notes/n_MDu-53qRVr4.jpg","w":1000,"h":668,"alt":"Hand holding sticky notes during an idea generation workshop","cap":"A participant holds sticky notes during an idea generation workshop. Quick-fire methods such as rapid ideation, mind mapping and SCAMPER aim to produce many ideas fast before the group sorts and judges them.","by":"FORTYTWO","title":"Real world:"},{"screen":"Planning designs: rough sketches, mood boards and style guides","src":"img/notes/n_HszbGgaGjOg.jpg","w":1000,"h":667,"alt":"Flat lay of printed images, colour samples and materials arranged as a mood board","cap":"Printed images, colours and materials are arranged together as a mood board. Collecting visuals like this sets the look and feel of a project before a style guide fixes the exact colours, fonts and rules.","by":"Fiona Murray-deGraaff","title":"Real world:"},{"screen":"Storyboarding: planning the visual sequence","src":"img/notes/n_gZmJWOoq5eI.jpg","w":1000,"h":750,"alt":"Hand-drawn sketches and handwritten notes on sheets of paper","cap":"Hand-drawn sketches sit alongside handwritten notes on paper. A storyboard works the same way, pairing a quick drawing of each shot with notes on action, sound and timing to plan the visual sequence.","by":"Nebular","title":"Real world:"},{"screen":"Timelines, Gantt charts and the production schedule","src":"img/notes/n_drg6s76J8YU.jpg","w":1000,"h":667,"alt":"Man writing on a large wall calendar","cap":"A man writes dates on a large wall calendar. A production schedule or Gantt chart does the same job for a media project, showing when each task starts, how long it takes and which deadlines depend on it.","by":"LOGAN WEAVER","title":"Real world:"},{"screen":"Factors affecting creation and the virtuous cycle","src":"img/notes/n_1tAtO-9HYNM.jpg","w":1000,"h":590,"alt":"People sitting on chairs arranged in a circle on grass","cap":"People sit in a circle on the grass, sharing ideas as a community. In a virtuous cycle, feedback from audiences and peers feeds back into the work, so each round of creation improves the next.","by":"Dorota Trzaska","title":"Real world:"},{"screen":"Prototypes, idea validation and implementation","src":"img/notes/n_gcHFXsdcmJE.jpg","w":1000,"h":667,"alt":"Hands drawing a wireframe layout for a mobile app on paper","cap":"Hands sketch a paper wireframe for an app screen. A quick, low-cost prototype like this can be shown to users to test and validate the idea before time and money go into building the real product.","by":"Kelly Sikkema","title":"Real world:"}],"M1U2B":[{"screen":"Composition decides what the eye sees first","src":"img/notes/n_DxNMHyoY1tk.jpg","w":1000,"h":750,"alt":"Aerial view of a small white boat on clear turquoise water","cap":"From above, a single white boat stands out against an expanse of turquoise water. The composition makes the eye go straight to the boat first, because contrast and empty space around it direct attention.","by":"Matthew McBrayer","title":"Real world:"},{"screen":"The golden ratio gives harmonious proportion","src":"img/notes/n_2bKHyFH_S7o.jpg","w":1000,"h":667,"alt":"Cut nautilus shell showing its spiral chambers on a black background","cap":"A halved nautilus shell reveals chambers that grow outward in a smooth spiral. Its proportions are often used to illustrate the golden ratio, the proportion designers borrow to make layouts and images feel balanced and harmonious.","by":"Content Pixie","title":"Real world:"},{"screen":"One clear point of interest earns prominence","src":"img/notes/n_uBnB37sufYE.jpg","w":1000,"h":667,"alt":"Lone person paddling a canoe across a wide turquoise ocean","cap":"One canoeist paddles alone across a wide turquoise ocean. With nothing else competing for attention, the small figure becomes the single clear point of interest, showing how isolation gives an element prominence.","by":"Nathalie Lays","title":"Real world:"},{"screen":"Perspective, camera angles and lighting","src":"img/notes/n_jkZs3Oi9pq0.jpg","w":1000,"h":667,"alt":"Person holding a camera up to their eye to take a photograph","cap":"A photographer raises a camera to frame a shot. Where they stand, how high or low they hold the camera and where the light falls all change the perspective and mood of the final image.","by":"Ailbhe Flynn","title":"Real world:"},{"screen":"Seven layout principles (1 to 4)","src":"img/notes/n_NmSPbe0bDtc.jpg","w":1000,"h":800,"alt":"Printed design books and paper brochures laid out on a surface","cap":"Printed design books and brochures are laid out side by side. Each page shows layout principles at work, such as alignment, balance, contrast and grouping, which guide the reader through text and images.","by":"2H Media","title":"Real world:"},{"screen":"Layout principles 5 to 7","src":"img/notes/n_g_w1Ndvq3Z0.jpg","w":1000,"h":750,"alt":"Open brochure showing columns of text alongside photographs","cap":"An open brochure combines columns of text with photographs. Repeating styles, leaving white space and keeping a clear hierarchy help a spread like this stay organised and easy to read.","by":"Sergio Alcázar Mondéjar","title":"Real world:"},{"screen":"A 2D storyboard frame plans the shot","src":"img/notes/n_lytupCDJuSg.jpg","w":1000,"h":667,"alt":"Mirrorless camera screen framing a group of people being photographed","cap":"A camera's screen frames a group of people before the shot is taken. A 2D storyboard frame plans exactly this view in advance: who is in shot, how large they appear and where the camera sits.","by":"Luke Lung","title":"Real world:"},{"screen":"Interactive design answers what a user does next","src":"img/notes/n_LRzkT1gIU8A.jpg","w":1000,"h":667,"alt":"Man pointing at the touchscreen of a public information kiosk","cap":"A man reaches out to tap a touchscreen information kiosk. Good interactive design makes the next step obvious, so a first-time user knows where to touch and what will happen when they do.","by":"Kate Trysh","title":"Real world:"},{"screen":"Learnability, predictability and feedback","src":"img/notes/n_xkArbdUcUeE.jpg","w":1000,"h":668,"alt":"Card payment terminal printing a paper receipt","cap":"A card payment terminal prints a receipt after a transaction. The beep, on-screen message and printed slip are feedback that confirm the action worked, and the familiar steps make the device learnable and predictable.","by":"Towfiqu barbhuiya","title":"Real world:"},{"screen":"Evaluate any app with two sets of questions","src":"img/notes/n_sScmok4Iq1o.jpg","w":1000,"h":750,"alt":"Smartphone in a hand displaying a dashboard app with weather and traffic information","cap":"A smartphone shows a dashboard app with weather and traffic panels. Evaluating an app like this means asking whether it meets its purpose and whether it is easy and pleasant for its users to operate.","by":"Balázs Kétyi","title":"Real world:"}],"M1U3":[{"screen":"Indigenous content shapes Caribbean creativity","src":"img/notes/n_78z3qaiYN8I.jpg","w":1000,"h":664,"alt":"Woman in a purple feathered carnival costume at Carnival in Port of Spain, Trinidad and Tobago","cap":"A masquerader in a purple feathered costume takes part in Carnival in Port of Spain, Trinidad and Tobago. Carnival design, music and movement are indigenous content that Caribbean digital creators draw on for colour, rhythm and stories.","by":"Holger Woizick","title":"Real world:"},{"screen":"Where culture shows up in evolving technology","src":"img/notes/n_Od9Yl_9f2S8.jpg","w":1000,"h":667,"alt":"Group of people holding up mobile phones to take pictures","cap":"A crowd holds up mobile phones to take pictures. Everyday technology now records and shares cultural moments instantly, so traditions appear in photos, videos and social media posts as well as in person.","by":"Prakriti Khajuria","title":"Real world:"},{"screen":"Screening, critique and observation","src":"img/notes/n_23LET4Hxj_U.jpg","w":1000,"h":667,"alt":"Audience seated in rows in a darkened cinema watching the screen","cap":"An audience sits in a darkened cinema watching a film. Screening work to viewers and observing how they react is the starting point for honest critique of what works and what needs to change.","by":"Jake Hills","title":"Real world:"},{"screen":"Screening techniques","src":"img/notes/n_0RoIEgga6vs.jpg","w":1000,"h":667,"alt":"Silhouetted people looking at a large bright projection screen","cap":"People stand silhouetted in front of a large projection screen. Planned screening techniques, such as a test audience, a group viewing and a feedback form, turn a simple showing like this into useful evidence.","by":"Adrien Olichon","title":"Real world:"},{"screen":"Case studies: Caribbean animation","src":"img/notes/n_5kTuOxF7C48.jpg","w":1000,"h":667,"alt":"Tablet displaying a digital illustration on a desk","cap":"A tablet displays a digital illustration in progress. Animated films often begin with drawings like this, made into characters and backgrounds before being brought to life frame by frame, which is how studios develop original stories.","by":"YongGuang Tian","title":"Real world:"},{"screen":"Case studies: film, games, apps, music videos and digital art","src":"img/notes/n_X6QffKLwyoQ.jpg","w":1000,"h":668,"alt":"Hands holding a black video game controller","cap":"A player grips a video game controller. Games sit alongside film, apps, music videos and digital art as media forms that can carry a culture's stories, settings and characters to audiences around the world.","by":"Sam Pak","title":"Real world:"},{"screen":"Indigenous versus imported content","src":"img/notes/n_n3UU0riHP6Y.jpg","w":1000,"h":657,"alt":"Black and white photo of a decorated wooden gingerbread-style house in Windward, Carriacou, Grenada","cap":"A gingerbread-style wooden house stands in Windward, Carriacou, Grenada. Local architecture like this is indigenous content rooted in a place, unlike imported media that shows audiences other countries' streets and stories.","by":"Hugh Whyte","title":"Real world:"},{"screen":"Authenticity, representation and stereotypes","src":"img/notes/n_RAZ4ArwfydM.jpg","w":1000,"h":667,"alt":"Women in colourful costumes at Chaguanas Carnaval 2025","cap":"Women in colourful costumes take part in Chaguanas Carnaval 2025. Showing real people at real events, in their own context, gives authentic representation rather than a stereotype of what outsiders expect.","by":"Anton Acosta","title":"Real world:"},{"screen":"Supporting local creators: policy, funding, community and festivals","src":"img/notes/n_TpL3BnJ3ZAQ.jpg","w":1000,"h":667,"alt":"Festival crowd waving flags, including the flag of Barbados","cap":"A festival crowd waves flags, including the flag of Barbados. Festivals like this bring communities together and give local creators a stage, an audience and a reason for sponsors and funders to support them.","by":"Kyle Hinkson","title":"Real world:"}],"M1U4":[{"screen":"A platform is the medium that carries digital content","src":"img/notes/n_70ku6P7kgmc.jpg","w":1000,"h":667,"alt":"Person holding and using a smartphone","cap":"A person holds a smartphone showing an app screen. The phone and the apps on it are platforms: the media that carry digital content such as videos, music and posts from creators to their audience.","by":"Christian Wiediger","title":"Real world:"},{"screen":"Where content lives: eight platform types","src":"img/notes/n_fxoAc0qOT5I.jpg","w":1000,"h":667,"alt":"Smartphone screen displaying a list of web search results","cap":"A phone screen shows a list of search results. Each result can lead to a different kind of platform, such as a website, video service, social network or online store, where content lives and reaches its users.","by":"Zulfugar Karimov","title":"Real world:"},{"screen":"How each platform type works","src":"img/notes/n_Y4zNMW3pQAs.jpg","w":1000,"h":668,"alt":"Man and woman laughing together while looking at a phone","cap":"Two friends laugh together over something on a phone. Social and streaming platforms work by serving content to users, who then react, comment and share it, spreading it further to new viewers.","by":"Karthik Balakrishnan","title":"Real world:"},{"screen":"Six types of digital platform by access","src":"img/notes/n_0rC40Gbnm9w.jpg","w":1000,"h":667,"alt":"Brightly lit public kiosk with a screen and buttons","cap":"A brightly lit public kiosk offers a screen and buttons. A kiosk is one way people access digital content; others include phones, computers, smart TVs and consoles, each shaping what users can do.","by":"Edwin Rodriguez","title":"Real world:"},{"screen":"How formats work: compression, resolution and colour depth","src":"img/notes/n_RuTMP0iI_ek.jpg","w":1000,"h":667,"alt":"Tablet running photo editing software showing an image being adjusted","cap":"A tablet runs photo editing software with an image open. The size and quality of the saved file depend on its resolution, its colour depth and how strongly it is compressed when exported.","by":"Jye","title":"Real world:"},{"screen":"Six formats compared: MP4, MP3, PDF, PNG, JPEG, GIF","src":"img/notes/n_P2aOvMMUJnY.jpg","w":1000,"h":750,"alt":"Pile of old printed photographs and postcards","cap":"A pile of old printed photographs and postcards each hold a single still image. Digitally, the same pictures would be saved as JPEG or PNG files, while moving images, sound and documents need formats such as MP4, MP3 and PDF.","by":"Jon Tyson","title":"Real world:"},{"screen":"Selecting formats for purpose and audience","src":"img/notes/n_qc3sE5lGLbA.jpg","w":1000,"h":667,"alt":"Tablet and smartphone lying side by side on a table","cap":"A tablet and a smartphone lie side by side. Choosing a format means thinking about the device and audience: a small, compressed file loads quickly on a phone, while a larger, higher-quality file suits bigger screens.","by":"Lauren Mancke","title":"Real world:"},{"screen":"Importing, exporting, sharing and embedding","src":"img/notes/n_MJJ6COD4OJw.jpg","w":1000,"h":562,"alt":"Smartphone placed beside two open laptops on a desk","cap":"A smartphone sits beside two laptops on a desk. Media is constantly moved between devices like these: imported into software, exported in a chosen format, then shared as a link or embedded in a web page.","by":"Amith Nair","title":"Real world:"},{"screen":"Cross-platform compatibility","src":"img/notes/n_2mc2B5iX6as.jpg","w":1000,"h":664,"alt":"Laptop, tablet and smartphone arranged together on a desk","cap":"A laptop, tablet and smartphone sit together on a desk. Cross-platform compatibility means a file or website opens and displays properly on all of these, whatever the screen size or operating system.","by":"Firmbee.com","title":"Real world:"},{"screen":"Paper 02 format conversion tips","src":"img/notes/n_SPdExUnQ1Qk.jpg","w":1000,"h":667,"alt":"Three women concentrating on work at laptop computers","cap":"Three content editors concentrate on tasks at their laptops. In a practical exam, working carefully and checking each converted file's format, size and quality before submitting avoids losing marks.","by":"Van Tay Media","title":"Real world:"}],"M1U5":[{"screen":"Image manipulation: layers, selections and masks","src":"img/notes/n_PevdsGAUrKA.jpg","w":1000,"h":667,"alt":"Laptop screen showing photo editing software with an image open","cap":"A laptop runs photo editing software with an image open for adjustment. Programs like this let editors work on separate layers, select precise areas and use masks to change one part of a picture without harming the rest.","by":"Zulfugar Karimov","title":"Real world:"},{"screen":"Compositing step by step","src":"img/notes/n_EUAKcWCzZfY.jpg","w":1000,"h":563,"alt":"Woman holding a smartphone with a plain green screen","cap":"A woman holds a phone showing a plain green screen. In compositing, that solid green area is keyed out and replaced with another image or video, combining separate sources step by step into one believable picture.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Sound editing and mixing in Audacity","src":"img/notes/n_KGyzk-EvTwQ.jpg","w":1000,"h":667,"alt":"Man adjusting faders on a sound mixing console","cap":"A man adjusts faders on a sound mixing console. Audio editing software recreates this desk on screen, letting you trim clips, balance the volume of each track and blend voice, music and effects into one mix.","by":"Bee Balogun","title":"Real world:"},{"screen":"Audio export formats: MP3, WAV and OGG","src":"img/notes/n_gKKB13zJ1ss.jpg","w":1000,"h":667,"alt":"Podcast microphone on a stand","cap":"A podcast microphone stands ready to record. Once recording and editing are done, the audio is exported as uncompressed WAV for maximum quality, or as smaller compressed MP3 or OGG files for streaming and sharing.","by":"Jukka Aalho","title":"Real world:"},{"screen":"The language of media","src":"img/notes/n_WM0LjvwOX3Q.jpg","w":1000,"h":563,"alt":"Black and white photo of a man facing a professional video camera","cap":"A man faces a professional video camera in black and white. Choices such as shot size, camera angle, colour and lighting form the language of media, telling viewers how to feel about the person on screen.","by":"Revolver Creative Company","title":"Real world:"},{"screen":"Pre-production documents and script formats","src":"img/notes/n_aYDIuBWzSc4.jpg","w":1000,"h":667,"alt":"Film clapperboard marked for take three","cap":"A clapperboard is marked for take three. The scene and take numbers on it link each clip back to the script and shot list, the pre-production documents that keep a shoot organised.","by":"Leuchtturm Entertainment","title":"Real world:"},{"screen":"Capturing video: devices, camera settings and stabilisation","src":"img/notes/n_yAH7J59F_74.jpg","w":1000,"h":667,"alt":"Camera operator filming a person outdoors using a camera on a gimbal","cap":"A camera operator films a person outdoors using a gimbal. The gimbal stabilises the camera so moving shots stay smooth, while settings such as frame rate, focus and exposure control how the footage looks.","by":"Robin WOEHL","title":"Real world:"},{"screen":"Recording sound for video: sound is half the picture","src":"img/notes/n_sOJGap513II.jpg","w":1000,"h":667,"alt":"Microphone on a boom pole held up outdoors during filming","cap":"A microphone on a boom pole is held up outdoors during filming. Getting the mic close to the speaker, just out of frame, captures clear dialogue, because poor sound spoils a video faster than poor pictures.","by":"Naomi August","title":"Real world:"},{"screen":"Lighting for video","src":"img/notes/n_O8AtzoQcnY4.jpg","w":1000,"h":667,"alt":"Photography and video studio with a light, tripod and backdrop","cap":"A photography and video studio is set up with a light, tripod and backdrop. Positioning lights like this as key, fill and back lights shapes the subject, controls shadows and sets the mood of a scene.","by":"KOBU Agency","title":"Real world:"},{"screen":"Video editing: the edit workflow in OpenShot and WeVideo","src":"img/notes/n_zE3jMxLFCIg.jpg","w":1000,"h":667,"alt":"Computer monitor showing a video editing timeline for a music video","cap":"A monitor shows a music video being cut on an editing timeline. The edit workflow follows the same order in any editor: import clips, arrange them on the timeline, trim, add audio, titles and transitions, then export.","by":"Kyle Loftus","title":"Real world:"},{"screen":"MP4 export settings for different platforms","src":"img/notes/n_X8uonmU2Ssw.jpg","w":1000,"h":667,"alt":"Live video control room with a wall of monitors showing multiple feeds","cap":"A live video control room shows many feeds on a wall of monitors. Video destined for different screens and platforms needs suitable export settings, such as resolution, frame rate and bitrate, so each version plays smoothly.","by":"Gabriel Weyand","title":"Real world:"},{"screen":"File management, licensing and publishing","src":"img/notes/n_VYfxkePredI.jpg","w":1000,"h":667,"alt":"Close-up of a silver and black hard disk drive","cap":"A close-up shows a hard disk drive, where project files are stored. Clear folder names, regular backups to a second drive or the cloud, and records of each asset's licence keep a project safe and ready to publish.","by":"Nick","title":"Real world:"},{"screen":"Cloud-based authoring tools: Figma and WeVideo","src":"img/notes/n_kp7qkHTgSKc.jpg","w":1000,"h":563,"alt":"Group of students gathered around a laptop, pointing at the screen and laughing","cap":"Students gather around a laptop in a lecture hall, pointing at the screen. Cloud-based authoring tools let a group like this open the same project in a browser and edit it together from any device.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"E-learning authoring suites","src":"img/notes/n_uWVWQ8gF8PE.jpg","w":1000,"h":667,"alt":"A woman in a grey sweater using a tablet at a wooden table","cap":"A learner works through content on a tablet. E-learning authoring suites use responsive design so the same interactive course, quiz or simulation works on a tablet, phone or laptop.","by":"Brooke Cagle","title":"Real world:"}],"M1U6":[{"screen":"What animation is: frames, keyframes, timing and spacing","src":"img/notes/n_hiIY0ZFeJNI.jpg","w":1000,"h":232,"alt":"A strip of film frames showing people walking","cap":"A strip of film frames shows people walking. Each still image is one frame; when the frames play quickly in sequence, at 24 frames per second for film, the small changes between them create the illusion of movement.","by":"Annie Spratt","title":"Real world:"},{"screen":"2D and 3D animation compared","src":"img/notes/n_SmGsf22cpi8.jpg","w":1000,"h":780,"alt":"A pencil sketch of a face on a notepad with a blue pen and eraser","cap":"A pencil sketch of a face on a notepad. Traditional 2D animation begins with drawings like this, which exist only in width and height; each new drawing differs slightly from the last to create motion.","by":"Christian Agbede","title":"Real world:"},{"screen":"The 12 principles of animation (1 to 6)","src":"img/notes/n_5xO6_jsDSfM.jpg","w":1000,"h":667,"alt":"A red ball resting on a concrete porch in the shade of a building","cap":"A red rubber ball on a concrete porch. Animators use a ball like this to practise squash and stretch: it flattens on impact and elongates when moving fast, while keeping the same volume.","by":"Trương Tuyết Ly","title":"Real world:"},{"screen":"The 12 principles of animation (7 to 12)","src":"img/notes/n_BLm_PzwRPBk.jpg","w":1000,"h":667,"alt":"A boy throwing a frisbee on the beach at sunset","cap":"A boy throws a frisbee on a beach at sunset. His swinging arm and the frisbee's curving flight both follow arcs, the principle that makes organic motion look natural rather than mechanical.","by":"Rachel Spina","title":"Real world:"},{"screen":"Straight-ahead action vs pose-to-pose","src":"img/notes/n_gpNmA7gWfss.jpg","w":1000,"h":667,"alt":"Waves splashing against a rock","cap":"A wave splashes against a rock. Unpredictable effects such as water, splashes, fire and smoke suit straight-ahead action, drawn frame by frame so the movement stays fluid and spontaneous.","by":"Janosch Lino","title":"Real world:"},{"screen":"Strengths of each style and the animator's toolkit","src":"img/notes/n_gSJBjyX6Jbs.jpg","w":1000,"h":667,"alt":"A person drawing a cartoon character with a large head on white paper","cap":"An artist sketches a cartoon character by hand. Stylised 2D drawing like this lets animators exaggerate shapes and emotion freely, though every new pose or angle has to be drawn again.","by":"Christian Agbede","title":"Real world:"},{"screen":"2D bouncing ball: step by step","src":"img/notes/n_BfphcCvhl6E.jpg","w":1000,"h":653,"alt":"A basketball dropping beneath a basketball hoop","cap":"A basketball drops beneath a hoop. A real ball like this slows near the top of each bounce and speeds up near the ground, which is exactly what the timing chart in the bouncing-ball exercise records.","by":"Markus Spiske","title":"Real world:"},{"screen":"Tweening in Adobe Animate (formerly Flash) and free 2D tools","src":"img/notes/n_yk9VXp4W5-Q.jpg","w":1000,"h":667,"alt":"A video editing timeline with blue and purple clips on a dark screen","cap":"A timeline in editing software shows clips laid out over time. Animation tools use a similar timeline: the animator sets keyframes on it and the software tweens, calculating the inbetween values.","by":"Peter Stumpf","title":"Real world:"},{"screen":"3D modelling fundamentals","src":"img/notes/n_3f6pnaW0k_E.jpg","w":1000,"h":667,"alt":"A curving geodesic dome structure built from triangular panels","cap":"A curving dome is built from many flat triangular panels. A 3D polygon mesh works the same way: vertices joined by edges enclose flat faces, and enough small faces together form a smooth-looking curved surface.","by":"Harvey Abayasiri","title":"Real world:"},{"screen":"3D bouncing ball in Blender: step by step","src":"img/notes/n_lLZQcmullqA.jpg","w":1000,"h":664,"alt":"A volleyball lying in the sand on a beach","cap":"A volleyball lies on the sand. In Blender, a UV sphere on a floor plane recreates this scene; the ball's origin is moved to its base so it squashes against the ground when it lands.","by":"Cameron Edwards","title":"Real world:"},{"screen":"3D interpolation and the Graph Editor","src":"img/notes/n_pONBhDyOFoM.jpg","w":1000,"h":648,"alt":"A white wind turbine against a blue sky","cap":"A wind turbine against a blue sky. Its blades turn at a steady, constant speed, so an animator would use linear interpolation, a straight line in the Graph Editor, rather than the default Bezier ease in and out.","by":"Nicholas Doherty","title":"Real world:"},{"screen":"A basic walk cycle","src":"img/notes/n_upO2WYtglUQ.jpg","w":1000,"h":563,"alt":"A man walking down a sidewalk in front of a white wall","cap":"A man walks along a sidewalk. Observing real walkers shows the key poses of a walk cycle: contact, down, passing and up, with the arms swinging opposite to the legs.","by":"Samyuktha Nair","title":"Real world:"},{"screen":"Render and export settings","src":"img/notes/n_2fJptbZ5QnE.jpg","w":1000,"h":667,"alt":"Close-up of the inside of a desktop computer with glowing fans and lights","cap":"The inside of a desktop PC with glowing cooling fans. Rendering turns a scene into finished frames and works this hardware hard, which is why a fast engine such as Eevee suits school computers better than slower Cycles.","by":"Brian Jones","title":"Real world:"}],"M1U7":[{"screen":"What is digital collaboration?","src":"img/notes/n_smgTvepind4.jpg","w":1000,"h":750,"alt":"A laptop screen showing a video call with a grid of participants, beside a coffee mug","cap":"A laptop shows a video call with many participants. This is digital collaboration in action: people in different places talking, organising tasks and working towards one shared goal without meeting in person.","by":"Chris Montgomery","title":"Real world:"},{"screen":"Three jobs collaboration tools do","src":"img/notes/n_JXyY3jRV9oI.jpg","w":1000,"h":663,"alt":"A whiteboard with sticky notes arranged in columns for project planning","cap":"A whiteboard holds sticky notes arranged in columns. This is the paper version of a project management tool such as Trello: each column shows a stage, so the whole team can see task progress at a glance.","by":"Paymo","title":"Real world:"},{"screen":"Collaboration tools and their uses","src":"img/notes/n_eTgMFFzroGc.jpg","w":1000,"h":667,"alt":"A laptop showing a video call with several participants, next to a houseplant","cap":"A laptop shows a team on a video call. Tools such as Microsoft Teams, Google Meet and Slack let a digital media team meet, chat by topic and share files from different places.","by":"Compagnons","title":"Real world:"},{"screen":"Electronic communities","src":"img/notes/n_8po6zR17PqE.jpg","w":1000,"h":664,"alt":"A person standing near a tree silhouetted against a colourful sunset","cap":"A sunset photograph taken in Curaçao. Shots like this are what members share in an online photography community, where others comment, give tips on exposure and, over time, build real relationships.","by":"Jabneel Statia","title":"Real world:"},{"screen":"Advantages of digital collaboration","src":"img/notes/n_nomAp6_KVXU.jpg","w":1000,"h":667,"alt":"A world map with pins marking different locations","cap":"A world map is marked with pins in many countries. This shows global reach, a key advantage of digital collaboration: a small island agency can work with clients, freelancers and the diaspora anywhere.","by":"Leandro Barreto","title":"Real world:"},{"screen":"Disadvantages and how to reduce them","src":"img/notes/n_Oop9PD4c8jA.jpg","w":1000,"h":667,"alt":"Palm trees bending in strong wind under a cloudy sky","cap":"Palm trees bend in strong wind under a grey sky. Storms like this can cause power cuts and outages, so teams reduce the risk with offline modes, local backups and asynchronous work.","by":"Sean Foster","title":"Real world:"},{"screen":"Advantages and disadvantages of electronic communities","src":"img/notes/n__1j7_atc0z8.jpg","w":1000,"h":667,"alt":"A group of volunteers standing together outdoors during a clean-up","cap":"Volunteers gather for an outdoor clean-up. An online group can give ordinary people leverage, reaching supporters far beyond the neighbourhood, and its interaction can lead to safe, organised physical meetings like this one.","by":"OCG Saving The Ocean","title":"Real world:"},{"screen":"Self-directed vs collaborative activities, roles and responsibilities","src":"img/notes/n_RjMUzVHrKx8.jpg","w":1000,"h":667,"alt":"A man wearing headphones sitting in front of a laptop","cap":"A learner works alone at a laptop with headphones on. This is self-directed digital learning, such as following a tutorial at his own pace; it builds independence but needs self-motivation.","by":"Nubelson Fernandes","title":"Real world:"},{"screen":"Netiquette and professional conduct","src":"img/notes/n_BjhUu6BpUZA.jpg","w":1000,"h":667,"alt":"Hands holding a smartphone and typing a message","cap":"A person types a message on a smartphone. Before sending, good netiquette applies: write clearly, avoid ALL CAPS, critique the work rather than the person and use the right channel.","by":"Priscilla Du Preez","title":"Real world:"},{"screen":"Evidence of collaboration for the SBA","src":"img/notes/n_05HLFQu8bFw.jpg","w":1000,"h":665,"alt":"Rows of colourful ring binders organised on office shelves","cap":"Rows of labelled ring binders on office shelves. Your SBA portfolio works the same way, but digitally: dated screenshots, meeting notes and uploads stored in an organised folder prove your collaboration trail.","by":"Viktor Talashuk","title":"Real world:"}],"M1U8":[{"screen":"Promotional campaigns and social networking","src":"img/notes/n_Dnkr_lmdKi8.jpg","w":1000,"h":667,"alt":"A large blank billboard standing outdoors against the sky","cap":"A blank outdoor billboard waits for a message. A promotional campaign decides what goes on spaces like this, and on social networks, as a planned series of coordinated messages aimed at one goal.","by":"Kate Trysh","title":"Real world:"},{"screen":"Content marketing, text messaging and WhatsApp","src":"img/notes/n_Hg3BHX6U5jg.jpg","w":1000,"h":660,"alt":"Two men wearing headphones recording a podcast at a wooden table in a studio","cap":"Two people record a podcast interview in a studio. Podcasts are a form of content marketing: they attract and keep an audience with useful long-form talk, building trust before any sale.","by":"Austin Distel","title":"Real world:"},{"screen":"Guerrilla marketing and viral marketing","src":"img/notes/n_ZSe8Zow2SfY.jpg","w":1000,"h":667,"alt":"Chalk drawings and handwritten messages covering a city pavement","cap":"Chalk drawings and messages cover a pavement in East London. Guerrilla marketing uses cheap, unexpected spaces like this to catch passers-by off guard, and a striking piece can then spread virally as people photograph and share it.","by":"Euronewsweek Media","title":"Real world:"},{"screen":"Guerilla marketing trades budget for surprise","src":"img/notes/n_JNuKyKXLh8U.jpg","w":1000,"h":667,"alt":"Person in a crowd filming a live concert on a smartphone","cap":"A concert-goer films the stage on a phone. Guerrilla campaigns swap big media budgets for surprise at events like this, counting on the audience to record and share the stunt for free.","by":"Noiseporn","title":"Real world:"},{"screen":"Cross-platform and influencer marketing","src":"img/notes/n_JDwWjf4x8ss.jpg","w":1000,"h":667,"alt":"Man filming himself with a camera while checking the shot on a monitor","cap":"A man films himself while checking the shot on a monitor. Influencer marketing relies on creators like this producing their own content, which a brand can then share across several platforms to reach the creator's followers.","by":"Detail .co","title":"Real world:"},{"screen":"A unified cross-platform strategy","src":"img/notes/n_WWNiWTsS5cY.jpg","w":1000,"h":667,"alt":"A palm-lined street with blank white billboards beside a building","cap":"Blank billboards line a palm-fringed street. Outdoor and print space is one part of a cross-platform mix, and the same logo, colours and message should carry across billboards, social media and email.","by":"Kate Trysh","title":"Real world:"},{"screen":"Email marketing with Mailchimp, Constant Contact and GetResponse","src":"img/notes/n_UpTHgRJsifs.jpg","w":1000,"h":667,"alt":"Vintage brass mail slot marked LETTERS set into a brick wall","cap":"An old letterbox slot marked LETTERS is set into a brick wall. Email marketing platforms are the digital version, delivering a brand's messages straight into each subscriber's inbox at scale.","by":"Genevieve Ridgway","title":"Real world:"},{"screen":"Eight types of email campaign and six strategies","src":"img/notes/n_KB0Ipylp7dc.jpg","w":1000,"h":667,"alt":"Two carnival dancers in feathered costumes taking a selfie together","cap":"Two carnival dancers in Curaçao take a selfie in costume. Seasonal and event emails tie a campaign to occasions like Carnival, when audiences are already excited and more likely to open and act.","by":"Quinten de Graaf","title":"Real world:"},{"screen":"Planning a campaign step by step","src":"img/notes/n_FoKO4DpXamQ.jpg","w":1000,"h":669,"alt":"Open monthly planner calendar on a desk","cap":"An open monthly planner lays out the weeks ahead. Planning a campaign means setting goals, audience, channels and dates in order, so every post and email has its place on the calendar.","by":"Eric Rothermel","title":"Real world:"},{"screen":"Measuring campaign effectiveness","src":"img/notes/n_6EnTPvPPL6I.jpg","w":1000,"h":667,"alt":"Hand-drawn line graph on paper with a ruler and pens","cap":"A hand-drawn line graph tracks results over time. Measuring a campaign works the same way: plotting reach, clicks and sales shows whether the effort is paying off and what to change.","by":"Isaac Smith","title":"Real world:"}],"M1U9":[{"screen":"Commoditisation, pervasiveness and affordability","src":"img/notes/n_8dgFq8Vbelo.jpg","w":1000,"h":667,"alt":"Colour swatch cards spread across a designer's desk","cap":"Colour swatch cards are spread across a designer's desk. As design tools and resources become cheap and everywhere, choices once reserved for professionals are now affordable for anyone, which is what commoditisation and pervasiveness mean.","by":"Andy Brown","title":"Real world:"},{"screen":"Accessibility and adoption","src":"img/notes/n_J5zIt97NYxQ.jpg","w":1000,"h":667,"alt":"Information sign with raised Braille text beside a tourist landmark","cap":"A Braille information sign stands at the Trevi Fountain in Rome. Accessible design like this lets more people use a product or place, and the more people who can use it, the wider its adoption.","by":"Gabriella Clare Marino","title":"Real world:"},{"screen":"Designing for empowerment","src":"img/notes/n_5dFuO02OHh0.jpg","w":1000,"h":714,"alt":"Street vendor at a fruit stand holding a mobile phone","cap":"A street vendor holds a phone at a fruit stand. Design that empowers puts simple, affordable digital tools in the hands of small traders, helping them take orders, payments and customers on their own terms.","by":"Ali Mkumbwa","title":"Real world:"},{"screen":"Current trends: dark mode, neumorphism and glassmorphism","src":"img/notes/n_lTUyP3RaLpw.jpg","w":1000,"h":667,"alt":"Hand holding a glowing smartphone in a dark setting at night","cap":"A phone glows in a hand at night. Dark mode interfaces suit settings like this, cutting glare and eye strain, which is one reason the trend has spread across apps and operating systems.","by":"Andrew Guan","title":"Real world:"},{"screen":"Micro-interactions, immersive UI and motion design","src":"img/notes/n_5SFiVF4lfnM.jpg","w":1000,"h":762,"alt":"Finger pointing at and tapping a smartphone screen","cap":"A finger taps a smartphone screen. Each tap, swipe or like can trigger a micro-interaction, a small animated response that confirms the action and makes the interface feel alive.","by":"Jakub Żerdzicki","title":"Real world:"},{"screen":"AI-assisted design: tools, ethics and copyright","src":"img/notes/n_KZ83Shi7VZE.jpg","w":1000,"h":667,"alt":"Designer's desk workspace with computer and design equipment","cap":"A designer's workspace is set up for digital work. Software tools that suggest layouts or generate images now sit alongside the designer, raising questions about who owns the result and how it should be credited.","by":"Jakub Żerdzicki","title":"Real world:"},{"screen":"AR and VR in visual design","src":"img/notes/n_NN9HQkDgguc.jpg","w":1000,"h":668,"alt":"Person wearing a virtual reality headset","cap":"A person wears a virtual reality headset. VR places the viewer inside a fully designed digital space, so visual designers must think about depth, scale and movement, not just a flat screen.","by":"stephan sorkin","title":"Real world:"},{"screen":"Research tools for tracking trends","src":"img/notes/n_j1xHNw0zF4g.jpg","w":1000,"h":663,"alt":"A book open to a page of designs, with coloured markers on it","cap":"An editorial design book open beside markers. Designers study published work and case studies, as on Behance, to research styles and track how visual trends change over time.","by":"Alejandra Ríos","title":"Real world:"}],"M1U10":[{"screen":"What a project proposal is and why it matters","src":"img/notes/n_y02jEX_B0O0.jpg","w":1000,"h":751,"alt":"Fountain pen writing on lined paper","cap":"A fountain pen writes across lined paper. A project proposal starts the same way, by putting an idea into clear written form so that a teacher, client or funder can judge whether it is worth backing.","by":"Aaron Burden","title":"Real world:"},{"screen":"Proposal writing: the core sections","src":"img/notes/n_Ax8IA8GAjVg.jpg","w":1000,"h":678,"alt":"Person writing and organising notes on white paper at a desk","cap":"A person sets out a strategy in handwritten notes. Drafting a proposal means organising ideas into its core sections, such as the summary, aims, audience, method, timeline and budget, before writing them up fully.","by":"Brands&People","title":"Real world:"},{"screen":"Target audience and market analysis","src":"img/notes/n_81wLx-FAde4.jpg","w":1000,"h":667,"alt":"People browsing stalls at a busy outdoor market","cap":"Shoppers browse the stalls at an outdoor market. Market analysis asks who these customers are, what they want and who else is selling to them, so a project is aimed at a real audience.","by":"Sateesh Reddy Patlolla","title":"Real world:"},{"screen":"Methodology and timeline","src":"img/notes/n_qWwpHwip31M.jpg","w":1000,"h":667,"alt":"Person arranging paper notes and a process flow on a board","cap":"A designer arranges a process flow of paper notes on a board. A proposal's methodology and timeline do the same job, showing each stage of the work in order and when it will happen.","by":"Alvaro Reyes","title":"Real world:"},{"screen":"Sources of funding: the big picture","src":"img/notes/n_G-Aj03ckq0w.jpg","w":1000,"h":667,"alt":"Glass jar of coins with a handwritten house fund sign","cap":"Coins collect in a jar labelled as a house fund. Every project needs money from somewhere, whether personal savings, loans, investors or grants, and the funding section explains where it will come from.","by":"Sandy Millar","title":"Real world:"},{"screen":"Debt, equity and FFF","src":"img/notes/n_cfGG0niafjc.jpg","w":1000,"h":667,"alt":"Family of adults and children sharing a meal at a dinner table","cap":"A family shares a meal around the table. Friends, family and fools (FFF) funding often begins at a table like this, when relatives lend or invest money in a young person's first project.","by":"National Cancer Institute","title":"Real world:"},{"screen":"Angels, venture capital and equity financing","src":"img/notes/n_NzIV4vOBA7s.jpg","w":1000,"h":667,"alt":"Two people shaking hands across a wooden table","cap":"Two people shake hands across a table to seal an agreement. With angel or venture capital funding, a handshake like this usually means the investor gives money in exchange for a share of the business.","by":"Rock Staar","title":"Real world:"},{"screen":"Crowdfunding models and other funding terms","src":"img/notes/n_c-4vSR1Li-4.jpg","w":1000,"h":749,"alt":"People talking and buying at a market stall","cap":"Customers gather at a market stall, each spending a little. Crowdfunding works on the same idea, raising a project's money from many small backers rather than one large investor.","by":"K. K.","title":"Real world:"},{"screen":"Budget planning: itemised costs","src":"img/notes/n_xoU52jUVUXA.jpg","w":1000,"h":574,"alt":"Person holding a paper document beside a pen and calculator","cap":"A person checks figures on paper with a calculator close by. An itemised budget lists every cost line by line, such as equipment, software, printing and transport, so the total can be checked and justified.","by":"Kelly Sikkema","title":"Real world:"},{"screen":"Project pitching and visual pitch decks","src":"img/notes/n_gMsnXqILjp4.jpg","w":1000,"h":667,"alt":"Man standing and presenting to people seated at a table with laptops","cap":"A man presents to a small group seated around a table. A pitch is this kind of short, persuasive presentation, usually supported by a visual deck, aimed at winning approval or funding for a project.","by":"Campaign Creators","title":"Real world:"},{"screen":"Your SBA proposal: the 14 marks","src":"img/notes/n_6RTM8EsD1T8.jpg","w":1000,"h":667,"alt":"Woman writing notes in a book at a table","cap":"A student writes carefully in a notebook. Your SBA proposal is marked section by section, so checking each part against the mark scheme as you write helps you earn all 14 marks.","by":"Kyle Gregory Devaras","title":"Real world:"}],"M2U1":[{"screen":"What is digital publishing?","src":"img/notes/n_R6j4IlsCww0.jpg","w":1000,"h":667,"alt":"A person sitting in a chair reading articles on a tablet at sunset","cap":"A reader settles into an afternoon of articles on a tablet. This is digital publishing in action: long-form content such as magazines, reports and e-books delivered on an electronic device instead of on paper.","by":"Daniel Cañibano","title":"Real world:"},{"screen":"The eight key features of digital publishing platforms","src":"img/notes/n_jczSZ-L8rh8.jpg","w":1000,"h":667,"alt":"A tablet on a desk displaying a website with images and text","cap":"A tablet shows a published web page mixing images and text. Digital publishing platforms bring features like this together, letting creators format, publish and distribute the same content to readers on many devices.","by":"Detail .co","title":"Real world:"},{"screen":"Digital publishing platforms and tools","src":"img/notes/n_9BoqXzEeQqM.jpg","w":1000,"h":667,"alt":"Rows of second-hand books laid out on tables at an outdoor book market","cap":"An outdoor book market lets many sellers reach readers in one place. Platforms such as Amazon KDP, Apple Books and Kobo Writing Life do the same job online, letting authors upload, sell and distribute their work.","by":"Tom Hermans","title":"Real world:"},{"screen":"Content management systems (CMS)","src":"img/notes/n_Zk--Ydz2IAs.jpg","w":1000,"h":667,"alt":"A person at a computer writing a post in a website editor","cap":"Someone writes a new post in a website dashboard. That is how a content management system works: you type and organise content through an editor, and the CMS handles the code and design that display it.","by":"Fikret tozak","title":"Real world:"},{"screen":"ePub, EPUB 3, PDF and interactive e-books","src":"img/notes/n_LTgvD_JxOGI.jpg","w":1000,"h":667,"alt":"A hand holding a smartphone showing a page of an e-book","cap":"An e-book is being read on a small phone screen. Reflowable formats such as ePub let the text resize to fit any screen, while a fixed-layout PDF keeps the exact page design and is harder to read on a phone.","by":"João Paulo Carnevalli de Oliveira","title":"Real world:"},{"screen":"E-books, their advantages and disadvantages, and e-reader vs tablet","src":"img/notes/n_AlgJkCowDVA.jpg","w":1000,"h":667,"alt":"A woman reading on a handheld e-book reader while commuting","cap":"A commuter reads on a light e-reader. This shows the portability advantage of e-books: one slim device holds thousands of titles, and its e-ink screen is easier on the eyes than a bright tablet.","by":"bady abbas","title":"Real world:"},{"screen":"ISBN and metadata","src":"img/notes/n_2j0acCTvBWM.jpg","w":1000,"h":667,"alt":"Wooden library card catalogue drawers with small metal labels","cap":"A library card catalogue labels and sorts every book so it can be found. An ISBN and metadata (title, author, keywords, edition) do the same job for e-books, helping stores and search engines catalogue them.","by":"Ilya Semenov","title":"Real world:"},{"screen":"A brief history of the Internet","src":"img/notes/n_SsDZRqcCfSo.jpg","w":1000,"h":667,"alt":"A row of old beige desktop computers with boxy monitors on a desk","cap":"A row of old desktop computers recalls the early days of networked computing. Machines like these were the first to connect to the growing Internet that began with ARPANET in 1969.","by":"Mert Kahveci","title":"Real world:"},{"screen":"Web 1.0, 2.0, 3.0, broadband and mobile","src":"img/notes/n_yhJVLxcquEY.jpg","w":1000,"h":714,"alt":"Yellow and green fibre optic cables neatly connected to a panel","cap":"Fibre optic cables carry data as pulses of light. Broadband like this made the shift from read-only Web 1.0 to the video-rich, social Web 2.0 possible, because pages, streams and uploads could finally move quickly.","by":"Albert Stoynov","title":"Real world:"},{"screen":"Accessibility, global adoption and MMOGs","src":"img/notes/n_lfQyS-TnqEg.jpg","w":1000,"h":667,"alt":"Two people wearing headsets playing a game in front of computer monitors","cap":"Two players game side by side on networked computers. Massively multiplayer online games (MMOGs) extend this to thousands of players at once, but only for people with reliable Internet access and suitable devices.","by":"Alex Haney","title":"Real world:"},{"screen":"Activity: a digital presentation on the history of the Internet","src":"img/notes/n_09YBhnOHCr8.jpg","w":1000,"h":750,"alt":"Students in a classroom watching a presentation projected at the front","cap":"Students watch a classmate's projected presentation. Your history-of-the-Internet activity works the same way: plan clear slides, then deliver them to an audience who must follow your timeline and key points.","by":"SMKN 1 Gantar","title":"Real world:"}],"M2U2":[{"screen":"Writing for digital media: the core techniques","src":"img/notes/n_i8r3Kt2-mr8.jpg","w":1000,"h":667,"alt":"A hand holding a smartphone showing a list of news stories","cap":"Someone flicks through news stories on a phone, glancing at headlines rather than reading every word. Writing for screens means short paragraphs, clear headings and key words placed first, because readers scan.","by":"Rich Tervet","title":"Real world:"},{"screen":"Digital writing techniques: podcasts, video, audio slideshows and social media","src":"img/notes/n_RtHTiKnZ_tk.jpg","w":1000,"h":667,"alt":"A smartphone on a tripod recording a person speaking","cap":"A phone on a tripod records a speaker for a livestream. One simple set-up can produce podcast audio, video clips and social media posts, but each format needs its own writing technique.","by":"Detail .co","title":"Real world:"},{"screen":"Writing for podcasts","src":"img/notes/n_cQKceh3huwY.jpg","w":1000,"h":667,"alt":"A person wearing headphones at a laptop during a podcast discussion","cap":"A podcast host and guest in discussion. Podcast writing plans a script for the ear, with a clear opening and structure, before the episode is recorded and distributed through an RSS feed.","by":"Flipsnack","title":"Real world:"},{"screen":"Seven video script writing tips","src":"img/notes/n_zR_B_bFmnyg.jpg","w":1000,"h":563,"alt":"A man smiling and giving a thumbs-up while recording himself on a camera at home","cap":"A creator records a vlog at home, speaking straight to the camera. Video scripts must hold attention visually as well as verbally, so expression, gestures and setting all form part of the message.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Presenting on camera and writing for audio slideshows","src":"img/notes/n_FJK2EY52jTw.jpg","w":1000,"h":667,"alt":"A man in a white polo shirt standing in front of a video camera","cap":"A presenter stands ready in front of a video camera. On camera, dressing, posture, voice and background all affect how viewers judge you, so plan them as carefully as the words.","by":"Kyle Loftus","title":"Real world:"},{"screen":"Conceptualisation and creative planning","src":"img/notes/n_BoAbPMRKLS0.jpg","w":1000,"h":667,"alt":"A blue marker pen beside a pad of yellow sticky notes","cap":"Sticky notes and a marker ready for an ideas session. Jotting one idea per note supports divergent thinking, when a team generates many concepts before choosing and refining the strongest.","by":"Kelly Sikkema","title":"Real world:"},{"screen":"Planning tools: storyboards, scripts, mock-ups and wireframes","src":"img/notes/n_weRQAu9TA-A.jpg","w":1000,"h":667,"alt":"Hand-drawn sketches of phone app screens on white paper","cap":"Rough pencil sketches map out phone screens before any design work begins. Storyboards, mock-ups and wireframes like these let a team agree on content and flow cheaply, before production costs money.","by":"Hal Gatewood","title":"Real world:"},{"screen":"Web authoring tools","src":"img/notes/n_OqtafYT5kTw.jpg","w":1000,"h":668,"alt":"A computer monitor showing lines of colourful website code in an editor","cap":"A monitor displays the source code behind a website theme. Web authoring tools let you build pages visually, while still giving access to this underlying HTML and CSS when you need fine control.","by":"Ilya Pavlov","title":"Real world:"},{"screen":"Creativity within a Caribbean perspective","src":"img/notes/n_SUcMtHW252E.jpg","w":1000,"h":783,"alt":"People in colourful costumes taking part in a street carnival","cap":"Masqueraders in colourful costumes at Chaguanas Carnival 2025. Festivals like this are authentic Caribbean stories that content creators can tell from inside the culture, for audiences who recognise themselves.","by":"Anton Acosta","title":"Real world:"},{"screen":"Copyright law in digital content creation","src":"img/notes/n_05RXMOeiOVA.jpg","w":1000,"h":667,"alt":"A man kneeling on a street holding a camera to take a photograph","cap":"A photographer kneels to frame a shot. The moment he takes the photo, he owns its copyright, so nobody may copy, share or adapt it without his permission or a licence.","by":"Yuanzhe Ma","title":"Real world:"},{"screen":"Ethical standards: plagiarism, attribution, fair use and Creative Commons","src":"img/notes/n_nYToduYJH-c.jpg","w":1000,"h":667,"alt":"People studying at long tables in a large library reading room","cap":"People study in the New York Public Library. Good research uses other people's work, but ethical creators always attribute their sources, rather than presenting borrowed words or images as their own.","by":"Clay Banks","title":"Real world:"},{"screen":"Cybercrime and the consequences of infringement","src":"img/notes/n_mT7lXZPjk7U.jpg","w":1000,"h":667,"alt":"A red padlock resting on a black computer keyboard","cap":"A padlock on a keyboard stands for protecting digital work and data. Cybercrimes such as piracy, hacking and identity theft target content and systems, and offenders can face fines or prison.","by":"FlyD","title":"Real world:"}],"M2U3":[{"screen":"The design journey: from concept to interactive experience","src":"img/notes/n_HtBlQdxfG9k.jpg","w":1000,"h":563,"alt":"An architect drawing a building plan with a pencil and ruler","cap":"An architect works on a draft with pencil and ruler. A building moves from rough plan to finished structure in stages, and a digital product follows the same journey from concept to wireframe, mockup and interactive prototype.","by":"Daniel McCullough","title":"Real world:"},{"screen":"Wireframes and mockups","src":"img/notes/n_FvpVY7TpwNY.jpg","w":1000,"h":750,"alt":"A website wireframe displayed on a laptop screen on an office desk","cap":"A website wireframe on a laptop screen. Its grey boxes show only layout and structure, so the team can agree on the plan before a full-colour mockup is designed.","by":"Amper","title":"Real world:"},{"screen":"What is a prototype?","src":"img/notes/n_5QiGvmyJTsc.jpg","w":1000,"h":667,"alt":"A person using a laptop during a usability test session","cap":"A user tries out a product while being observed in a usability test. This is why prototypes exist: an incomplete version is put in front of real users so problems are found before the final build.","by":"UX Indonesia","title":"Real world:"},{"screen":"Four types of prototype","src":"img/notes/n_PomM7aa5m18.jpg","w":1000,"h":667,"alt":"A 3D printer building a yellow object from PLA filament","cap":"A 3D printer builds a physical object layer by layer. Not every prototype is a set of screens; a physical model like this answers different questions about size, shape and feel.","by":"Osman Talha Dikyar","title":"Real world:"},{"screen":"Concept maps: brainstorming with a purpose","src":"img/notes/n_fSWQPBxqClg.jpg","w":1000,"h":667,"alt":"A hand writing the word audience on a whiteboard with arrows","cap":"A hand writes \"audience\" on a whiteboard with arrows linking ideas. A concept map starts the same way: a central idea with connected branches, organising thoughts before any screen is drawn.","by":"Melanie Deziel","title":"Real world:"},{"screen":"Site maps: HTML sitemaps and XML sitemaps","src":"img/notes/n_3ykTik-GPEc.jpg","w":1000,"h":667,"alt":"Illuminated subway maps beside a plan your trip sign","cap":"Lit-up subway maps help travellers plan a trip. An HTML sitemap does the same for visitors, showing every page and how they connect, while an XML sitemap gives search engines that map.","by":"Angelica Hasbon","title":"Real world:"},{"screen":"Navigation charts: guiding visitors through your site","src":"img/notes/n_f4O046ELXlU.jpg","w":1000,"h":667,"alt":"Direction signs pointing to different destinations","cap":"Direction signs point people towards different destinations. A navigation chart plans these signposts for a website, mapping how visitors move from one page to the next.","by":"Daniel Brubaker","title":"Real world:"},{"screen":"Five types of website navigation","src":"img/notes/n_fSTjfMQ44YU.jpg","w":1000,"h":673,"alt":"A white and red menu board listing food items","cap":"A menu board groups choices so customers find what they want quickly. Website navigation menus, whether horizontal, dropdown or hamburger, do the same job of grouping pages for visitors.","by":"Ava Tyler","title":"Real world:"},{"screen":"Hierarchy maps and user pathways","src":"img/notes/n_B645igbiKCw.jpg","w":1000,"h":750,"alt":"The spreading trunk and branches of a large banyan tree","cap":"A banyan tree in Hawai'i spreads from one trunk into many branches. A hierarchy map works the same way, starting with broad categories at the top and narrowing down to specific pages.","by":"Emma Henderson","title":"Real world:"},{"screen":"Design principles 1: rule of thirds, composition, balance, alignment","src":"img/notes/n_PSD6ffClG0w.jpg","w":1000,"h":750,"alt":"A palm tree leaning over a beach shoreline on a sunny day","cap":"A palm tree frames the shore on Ile a Vache, Haiti. Placing the main subject off-centre and balancing it against sea and sky shows the rule of thirds and balance that also guide a good page layout.","by":"Claudia Altamimi","title":"Real world:"},{"screen":"Design principles 2: hierarchy, contrast, spacing, visual flow","src":"img/notes/n_H6eaxcGNQbU.jpg","w":1000,"h":667,"alt":"A pile of folded newspapers with large headlines","cap":"A pile of newspapers shows large bold headlines above smaller text. Newspapers use size, weight and contrast to show what matters most, the same visual hierarchy a web page uses with its H1 and subheadings.","by":"Tim Mossholder","title":"Real world:"},{"screen":"Cloud-based prototyping and authoring tools","src":"img/notes/n_Uywp-JHgVP4.jpg","w":1000,"h":667,"alt":"People working on laptops together around a table","cap":"A group works on laptops around one table. Cloud-based prototyping tools let a team like this edit and comment on the same design at the same time, with work saved online.","by":"Compagnons","title":"Real world:"},{"screen":"Step by step: a clickable wireframe in Figma","src":"img/notes/n_LdqA4jESqi0.jpg","w":1000,"h":667,"alt":"A tablet showing a design layout on a wooden table beside coffee","cap":"A tablet shows UI and UX wireframing in progress. Building a clickable wireframe in a tool such as Figma turns simple screens into linked frames that users can tap through.","by":"Sahand Babali","title":"Real world:"},{"screen":"When to use each, and designing with purpose","src":"img/notes/n_tZc3vjPCk-Q.jpg","w":1000,"h":667,"alt":"Watercolour sketches of several website page layouts","cap":"Hand-painted sketches show several website layouts side by side. Choosing whether a project needs sketches, a wireframe, a mockup or a prototype depends on its purpose, time and budget.","by":"Hal Gatewood","title":"Real world:"}],"M2U4":[{"screen":"Case study: Taste of Castries","src":"img/notes/n_tn4t2tVC9uQ.jpg","w":1000,"h":667,"alt":"Aerial view of a harbour town with buildings beside blue water","cap":"An aerial view of Castries shows the town wrapped around its harbour. This is the setting for the Taste of Castries case study, the model project you will follow from start to finish in this unit.","by":"Omar Eagle","title":"Real world:"},{"screen":"The seven-stage content cycle","src":"img/notes/n_bwOAixLG0uc.jpg","w":1000,"h":668,"alt":"A calendar with red push pins marking several dates","cap":"A calendar with dates marked by pins. Content teams schedule each stage, from planning and research to publishing and maintenance, so the content cycle keeps moving on time.","by":"Towfiqu barbhuiya","title":"Real world:"},{"screen":"Scope sets the boundaries before you write","src":"img/notes/n_JUQxv0DunZg.jpg","w":1000,"h":750,"alt":"A wooden split rail fence running along the edge of a green field","cap":"A split rail fence marks the edge of a park. Content scope works like this fence, setting clear boundaries for what you will create, for whom and why before you write a word.","by":"Jan Canty","title":"Real world:"},{"screen":"Research: find the gap, check the facts","src":"img/notes/n_yx17UuZw1Ck.jpg","w":1000,"h":667,"alt":"A black magnifying glass resting on white paper","cap":"A magnifying glass rests on a sheet of paper. Good research means looking closely: finding the gap in existing content and checking that every fact you publish is accurate and credible.","by":"Mediamodifier","title":"Real world:"},{"screen":"The creative brief: the contract for the content","src":"img/notes/n_xxHDLWmc1wE.jpg","w":1000,"h":667,"alt":"Two people at a table, one writing notes during a meeting","cap":"One person writes notes while another talks through a plan. A creative brief records what a meeting like this agrees, acting as the contract for what the team will make and for whom.","by":"Kaleidico","title":"Real world:"},{"screen":"Case study: write for Denise, not for everyone","src":"img/notes/n_U1QWCuJBxYo.jpg","w":1000,"h":602,"alt":"Aerial view of a cruise ship terminal beside a harbour town","cap":"The cruise ship terminal in St George's, Grenada, welcomes thousands of visitors. Writing for one persona, such as Denise stepping off a ship for a few hours, is clearer than writing for every cruise visitor.","by":"Hugh Whyte","title":"Real world:"},{"screen":"Readers scan in an F-shape, so write for scanners","src":"img/notes/n_c-UYHN0qbdU.jpg","w":1000,"h":563,"alt":"A hand holding a smartphone showing a news page","cap":"A reader scrolls through news on a smartphone. Most people scan pages like this rather than reading every word, so headings, short paragraphs and key words on the left help them find what they need.","by":"Amanz","title":"Real world:"},{"screen":"Check the licence before you publish anything","src":"img/notes/n_ehMNP0Ooj3M.jpg","w":1000,"h":667,"alt":"Rows of vinyl records in record store bins","cap":"Bins of vinyl records fill a record shop. Every song on them has an owner and a licence, and the same is true of any music, image, video or font you publish online.","by":"Mick Haupt","title":"Real world:"},{"screen":"SEO helps the right people find your content","src":"img/notes/n_d9ILr-dbEdg.jpg","w":1000,"h":664,"alt":"A magnifying glass lying next to a laptop","cap":"A magnifying glass beside a laptop suggests searching online. SEO helps search engines read and index your content so the right people find it when they search.","by":"Agence Olloweb","title":"Real world:"},{"screen":"Optimise images: right format, size and alt text","src":"img/notes/n_NcPpI6X59W4.jpg","w":1000,"h":667,"alt":"A woman editing photos on a computer at a desk","cap":"A woman edits photos on a computer. Before images go on the web they should be resized, compressed and saved in a suitable format such as WebP or JPEG, with alt text added.","by":"TourBox","title":"Real world:"},{"screen":"Great UX is readable, fast and accessible","src":"img/notes/n_4MoIpDcSlr4.jpg","w":1000,"h":750,"alt":"A person's hands on a braille display connected to a computer","cap":"A blind user reads with a braille screen reader. Accessible websites with alt text, clear headings and good structure let people like this use the content too.","by":"Compagnons","title":"Real world:"},{"screen":"Case study: review against the checklist","src":"img/notes/n_yKnIbJV0RbY.jpg","w":1000,"h":563,"alt":"A hand ticking off items on a digital checklist on a tablet","cap":"A hand ticks items off a checklist with a stylus. Reviewing content against a checklist before publishing catches errors in facts, readability and accessibility.","by":"Jakub Żerdzicki","title":"Real world:"}],"M2U5":[{"screen":"Great content needs tools and technique","src":"img/notes/n_2mZncc1MQX4.jpg","w":1000,"h":667,"alt":"Cameras and lenses neatly arranged on a wooden surface","cap":"Cameras and lenses are laid out ready for a shoot. Good web content starts with choosing the right tools, then using technique to shape the story and prepare it for the screen.","by":"Micah & Sammie Chaffin","title":"Real world:"},{"screen":"Cameras and capture devices for web content","src":"img/notes/n_mfWsMDdN-Ro.jpg","w":1000,"h":667,"alt":"A man in a black jacket holding a handheld camera outdoors","cap":"A man holds a handheld camera outdoors. Handheld cameras sit alongside phones, tablets and mounted devices as the main capture tools for web content.","by":"Andrés","title":"Real world:"},{"screen":"Depth of field and angles shape the feeling","src":"img/notes/n_MkmY_1ejJa0.jpg","w":1000,"h":667,"alt":"A pink flower in sharp focus against a soft blurred background","cap":"A pink flower is sharp while the background melts into blur. This shallow depth of field draws the eye straight to the subject and gives the image a soft, intimate feel.","by":"Jaime Lopes","title":"Real world:"},{"screen":"Open-source, industry-standard or cloud: match software to the task","src":"img/notes/n_CGpifH3FjOA.jpg","w":1000,"h":667,"alt":"A designer using a drawing tablet and laptop with colour swatches","cap":"A graphic designer works with a drawing tablet, laptop and colour charts. Choosing open-source, industry-standard or cloud software depends on the task, the budget and who needs to collaborate.","by":"Theme Photos","title":"Real world:"},{"screen":"Photo editing: protect the original, then make it web-ready","src":"img/notes/n_SL5d_8ywAAA.jpg","w":1000,"h":666,"alt":"A person editing a photo on a computer screen","cap":"A photographer edits an image on a computer. Working on a copy protects the original, then cropping, colour correction and export settings make the photo ready for the web.","by":"Glenn Carstens-Peters","title":"Real world:"},{"screen":"Practical task 1, \"Taste of English Harbour\"","src":"img/notes/n_fTIQgxtF1Xg.jpg","w":1000,"h":667,"alt":"A white plate of lobster served with a side salad","cap":"A plate of lobster with salad is the kind of restaurant photo used in this task. You will crop it to size, correct the colours, add the title text and export it under 400 KB.","by":"Meg von Haartman","title":"Real world:"},{"screen":"Audio: get it right at the source, then mix in layers","src":"img/notes/n_2jTu7H9l6JA.jpg","w":1000,"h":667,"alt":"Close-up of the faders and knobs on an audio mixer","cap":"An audio mixer has a separate channel and fader for each sound. Recording clean audio at the source, then layering and balancing tracks like this, gives a clear final mix.","by":"Nejc Soklič","title":"Real world:"},{"screen":"Creating a podcast step by step","src":"img/notes/n_ZDNyhmgkZlQ.jpg","w":1000,"h":667,"alt":"Studio microphone with pop shield and headphones on a desk in a home recording setup","cap":"A home podcasting setup: a condenser microphone with a pop shield, closed headphones and a desk stand. This is stage 2, gathering equipment, before you record, edit and publish your episodes.","by":"Will Francis","title":"Real world:"},{"screen":"Producing an audio slideshow","src":"img/notes/n_aV5xrpB0bwQ.jpg","w":1000,"h":632,"alt":"Assorted printed photographs spread out across a wooden table","cap":"Printed photographs laid out on a table, ready to be put in order. Sequencing images like this, on a storyboard, is the first step of the storyboard-first workflow before you record narration for each frame.","by":"Soragrit Wongsa","title":"Real world:"},{"screen":"Video: a hook, purposeful cuts and navigation cues","src":"img/notes/n_mQxttWjHFjA.jpg","w":1000,"h":671,"alt":"A computer on a desk showing video editing software with a timeline","cap":"Video editing software open on a desktop computer. Editors arrange clips on the timeline, trim them tightly, balance audio and add titles to turn raw footage into a finished video.","by":"Jakob Owens","title":"Real world:"},{"screen":"Web-ready means accessible and correctly exported","src":"img/notes/n_85UvN7XT_CA.jpg","w":1000,"h":563,"alt":"Two hands linking fingers against a black background, forming part of a sign","cap":"Hands forming the first half of the sign for \"friendship\" in American Sign Language. Deaf and hard-of-hearing viewers rely on accurate captions and transcripts, which is why every web video must be made accessible before publishing.","by":"Nic Rosenau","title":"Real world:"},{"screen":"Breadcrumbs for web pages and long videos","src":"img/notes/n_gnHASANfQzY.jpg","w":1000,"h":667,"alt":"Wooden footpath signpost with arms pointing in different directions","cap":"A footpath signpost showing walkers where they are and where each path leads. Breadcrumbs do the same on a website: they show your location in the hierarchy and let you jump back a level in one click.","by":"Matt Ashby","title":"Real world:"}],"M2U6":[{"screen":"Frame, walls, paint and electricity","src":"img/notes/n_kkdfOe0iRu8.jpg","w":1000,"h":667,"alt":"House under construction with exposed timber wall frames and roof trusses","cap":"A new home with only its timber frame and roof trusses in place. HTML is this frame and walls: it builds the structure first, before CSS adds the paint and JavaScript wires in the electricity.","by":"Troy Mortier","title":"Real world:"},{"screen":"How an HTML document is built","src":"img/notes/n_4hbJ-eymZ1o.jpg","w":1000,"h":667,"alt":"Lines of colour-coded HTML code in a code editor on a dark screen","cap":"Real HTML code in an editor, with tags, attributes and content shown in different colours. Each element follows the pattern of an opening tag, content and a closing tag that the browser reads to draw the page.","by":"Florian Olivo","title":"Real world:"},{"screen":"Try it in Notepad","src":"img/notes/n_5p_7M5MP2Iw.jpg","w":1000,"h":668,"alt":"Person in a long-sleeved top typing on a laptop keyboard","cap":"Someone typing directly on a laptop. You need nothing more than this, a plain text editor such as Notepad and a browser, to type out an HTML skeleton line by line and see your first page.","by":"Štefan Štefančík","title":"Real world:"},{"screen":"Tags, tidy nesting and a toolkit of tags","src":"img/notes/n_KcakynOH-6M.jpg","w":1000,"h":667,"alt":"Five colourful hand-painted wooden nesting dolls lined up on a white surface","cap":"Traditional nesting dolls, each fitting neatly inside the next. HTML nesting works the same way: the inner element must close before the outer one, so the smallest doll goes back in before the larger ones close.","by":"Jason Gooljar","title":"Real world:"},{"screen":"Hyperlinks and images","src":"img/notes/n_t1OalCBUYRc.jpg","w":1000,"h":665,"alt":"Close-up of a steel chain with interlocking links on a white background","cap":"A steel chain made of connected links. Hyperlinks connect pages in the same way: internal links join pages on one site, while external links join your site to other websites across the web.","by":"Edge2Edge Media","title":"Real world:"},{"screen":"First CSS: the style attribute, rules, selectors and the cascade","src":"img/notes/n_PtabTe6iJ_8.jpg","w":1000,"h":668,"alt":"Fan deck of colourful paper swatches spread out in a spectrum","cap":"A fan deck of colour swatches used to check printed and painted colours. In CSS you choose colours just as precisely, with properties such as color and background-color, remembering to use the American spelling.","by":"Mika Baumeister","title":"Real world:"},{"screen":"The box model, typography and colour","src":"img/notes/n_FEjgCeV3Hnk.jpg","w":1000,"h":669,"alt":"A framed picture hanging on a pink wall","cap":"A framed picture on a wall. It works like the CSS box model: the picture is the content, the space around it is padding, the frame is the border, and the wall space keeping other items away is the margin.","by":"Jael Coon","title":"Real world:"},{"screen":"Layout with flexbox and a simple grid","src":"img/notes/n_leOh1CzRZVQ.jpg","w":1000,"h":781,"alt":"Brown chicken eggs arranged in rows and columns in a cardboard carton","cap":"Eggs sitting neatly in a carton of rows and columns. CSS Grid arranges page boxes the same way in two directions, while flexbox lines items up along a single row or column.","by":"Erol Ahmed","title":"Real world:"},{"screen":"Embedding images, video, audio and widgets","src":"img/notes/n_aWHpV-ocThE.jpg","w":1000,"h":667,"alt":"Two seated men watching something together on a smartphone","cap":"Two people watching a video together on a phone. Video embedded with the HTML5 video element and its controls attribute lets visitors play, pause and adjust the volume right on your web page.","by":"Alex Suprun","title":"Real world:"},{"screen":"Print vs screen resolution, units and responsive media","src":"img/notes/n_Tzm3Oyu_6sk.jpg","w":1000,"h":668,"alt":"Large industrial printing machine with paper running through its rollers","cap":"An industrial printing machine laying ink on paper. Print is measured in dots per inch and uses CMYK ink, whereas screens use pixels and RGB light, so the same photo is prepared differently for each.","by":"Bank Phrom","title":"Real world:"},{"screen":"Mobile-first responsive design","src":"img/notes/n_NKvwME6VsRY.jpg","w":1000,"h":563,"alt":"Smiling woman in a yellow raincoat using her smartphone while walking with a coffee","cap":"A woman checking her phone while walking through town. Many visitors meet your site on a small screen on the move, which is why designers write the phone layout first and add rules for wider screens.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Multi-page site architecture","src":"img/notes/n_4UGmm3WRUoQ.jpg","w":1000,"h":750,"alt":"Hand-drawn website wireframe sketched on paper beside an orange pen","cap":"A hand-drawn website wireframe on paper. Sketching grey-box layouts like this fixes the structure of each page before any colour, images or code are added to the site.","by":"Compagnons","title":"Real world:"},{"screen":"Page design, UI and UX, accessibility and usability","src":"img/notes/n_Ylk5n_nd9dA.jpg","w":1000,"h":667,"alt":"A computer screen displaying a website home page","cap":"A blog home page shown on a computer screen. Good page design uses clear contrast, a consistent grid and readable text so that visitors can find and use content easily.","by":"Pankaj Patel","title":"Real world:"},{"screen":"Practical task: a main-street business page","src":"img/notes/n_iyv_FYF5kxQ.jpg","w":1000,"h":750,"alt":"Brightly painted colonial buildings and parked cars along a narrow sunny street","cap":"Brightly painted colonial buildings line a street in downtown Nassau, The Bahamas. Shops on streets like this are exactly the kind of main-street business you could build a one-page site for in this task.","by":"Yash Mannepalli","title":"Real world:"}],"M2U7":[{"screen":"Domains, URLs and DNS","src":"img/notes/n_xia11lqO5Qs.jpg","w":1000,"h":699,"alt":"Yellow oval plaque showing the number 57 on a white louvred door","cap":"A house number on a front door tells visitors where to find a home. A domain name does the same for a website, while DNS works like a directory that turns that name into the server's numeric IP address.","by":"iridial","title":"Real world:"},{"screen":"Types of web hosting","src":"img/notes/n_VHmBX7FnXw0.jpg","w":1000,"h":663,"alt":"Server rack with rows of blinking green status lights","cap":"A rack of servers with status lights glowing. A web host rents space on always-on machines like these; on shared hosting many sites share one server, while a VPS splits a server into private virtual machines.","by":"Domaintechnik","title":"Real world:"},{"screen":"Front end, back end, databases and CMS","src":"img/notes/n_y-XZf_TNRms.jpg","w":1000,"h":563,"alt":"Chef in a white coat chopping vegetables on a board in a kitchen","cap":"A chef preparing food in a restaurant kitchen. Like the kitchen, the back end works out of sight on the server, processing orders and data, while the front end is the dining room visitors see in their browser.","by":"Pylyp Sukhenko","title":"Real world:"},{"screen":"Forms, data collection, privacy and permissions","src":"img/notes/n_eXcF6L9pEug.jpg","w":1000,"h":667,"alt":"Hand holding a pen over a form on a blue clipboard","cap":"Someone filling in a paper form on a clipboard. A web form collects the same kind of details online, so it needs clear labels, only the fields it truly needs and the visitor's consent before their data is stored.","by":"Phil Hearing","title":"Real world:"},{"screen":"Passwords, 2FA, HTTPS and backups","src":"img/notes/n_hvbjTynPt7A.jpg","w":1000,"h":667,"alt":"A screen showing account settings with a verification prompt","cap":"An account settings screen asks for verification. Two-factor authentication adds a second proof of identity, such as a code, so a stolen password alone cannot open the account.","by":"Zulfugar Karimov","title":"Real world:"},{"screen":"Common website security threats","src":"img/notes/n_Fl3Rf_t8dMs.jpg","w":1000,"h":667,"alt":"A fishing hook hanging from a line against a pale blue background","cap":"A baited fishing hook dangling on its line. Phishing takes its name from this: a fake email, text or website is the bait, designed to hook people into handing over their passwords or payment details.","by":"Kaptured by Kasia","title":"Real world:"},{"screen":"Website builders vs hand-coded HTML","src":"img/notes/n_RcxR1aLw8X0.jpg","w":1000,"h":750,"alt":"Assorted colourful wooden building blocks","cap":"Ready-made wooden building blocks in different shapes and colours. Website builders work in a similar way: you assemble pages quickly from ready-made templates and blocks, but with less control than hand-coding every element in HTML.","by":"Michał Bożek","title":"Real world:"}],"M2U8":[{"screen":"Forms of digital publishing (1): websites, blogs, social, games and apps","src":"img/notes/n_GNVxujZ_CxU.jpg","w":1000,"h":667,"alt":"A woman using a gold tablet","cap":"A woman reads content on a tablet. Websites, blogs, social networks, apps and e-books are all forms of digital publishing that make content available to audiences on screens like this.","by":"Marek Levák","title":"Real world:"},{"screen":"Forms of digital publishing (2): podcasts, videos, e-books, newsletters and digital magazines","src":"img/notes/n_c1ZN57GfDB0.jpg","w":1000,"h":667,"alt":"Close-up of a silver and black condenser microphone in a dark studio","cap":"A condenser microphone set up in a studio. Microphones like this are where podcasts begin, one of several audio, video and text forms of digital publishing alongside e-books, newsletters and digital magazines.","by":"Jonathan Velasquez","title":"Real world:"},{"screen":"Classifying forms of digital publishing","src":"img/notes/n_4m4A6uIt43s.jpg","w":1000,"h":668,"alt":"People browsing through boxes of vinyl records sorted into sections","cap":"Shoppers browse records sorted into boxes by type. Classifying digital publishing works the same way: grouping each form by features such as its medium, how it is delivered and how the audience interacts with it.","by":"Oleg","title":"Real world:"},{"screen":"Evaluation criteria (1): accuracy, authority, usability and accessibility","src":"img/notes/n_v8uwMcKxvj4.jpg","w":1000,"h":667,"alt":"A magnifying glass held over a page of printed text","cap":"A magnifying glass held over printed text. Evaluating a publication means examining it closely in the same way: checking that the facts are accurate, the author has authority, and the content is usable and accessible.","by":"Spencer Liao","title":"Real world:"},{"screen":"Evaluation criteria (2): satisfaction, purpose, risk and security (plus extras)","src":"img/notes/n_FnA5pAzqhMM.jpg","w":1000,"h":668,"alt":"A golden padlock resting on a white computer keyboard","cap":"A padlock resting on a keyboard. It stands for the risk and security criterion, which asks whether a publication keeps users' data safe, alongside how satisfied users are and whether it achieves its purpose.","by":"Towfiqu barbhuiya","title":"Real world:"},{"screen":"Activity: forms of digital publishing","src":"img/notes/n_EA0-iajPYFE.jpg","w":1000,"h":563,"alt":"A group of students gathered around a laptop in a classroom","cap":"Students work on a project around a laptop. In this activity, groups define each form of digital publishing and then evaluate examples for accuracy, authority, usability and accessibility.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Comparing Caribbean content across the forms","src":"img/notes/n__Zua2hyvTBk.jpg","w":1000,"h":668,"alt":"A man sitting on a bench reading a newspaper","cap":"A man reads a printed newspaper on a bench. Many Caribbean newspapers now also publish online, so comparing the same news content in print, on websites and on social media shows each form's strengths and gaps.","by":"Roman Kraft","title":"Real world:"},{"screen":"Choosing the right form for an audience and purpose","src":"img/notes/n_F2KRf_QfCqw.jpg","w":1000,"h":667,"alt":"An audience seated in rows of chairs facing a stage at a conference","cap":"An audience seated at a conference. Before choosing a form of digital publishing, a publisher needs to understand who the audience is and what the content should achieve, just as a speaker plans a talk for the people in the room.","by":"Headway","title":"Real world:"}],"M2U9":[{"screen":"Hosted free, hosted paid and self-hosted platforms","src":"img/notes/n_2JJ3wBHu4_0.jpg","w":1000,"h":667,"alt":"A rack of servers with cables and indicator lights in a server room","cap":"A rack of servers in a server room. With a hosted platform, the provider runs machines like these for you. With self-hosting, you rent or manage the server yourself and take on the control and the responsibility that come with it.","by":"Kevin Ache","title":"Real world:"},{"screen":"Publishing a blog: frequency, SEO and community","src":"img/notes/n_xcvXS6wDCAY.jpg","w":1000,"h":667,"alt":"A woman's hands at a desk writing in a blank notebook","cap":"A woman writes in a notebook at her desk. Good bloggers plan ahead in a similar way: they draft posts, keep a regular publishing schedule, choose keywords for SEO and reply to readers to build a community.","by":"Kelly Sikkema","title":"Real world:"},{"screen":"Writing on Wikipedia","src":"img/notes/n_o3sl4dhYhZE.jpg","w":1000,"h":750,"alt":"Close view of a row of compact encyclopedia volumes on a shelf","cap":"A row of printed encyclopedia volumes. Wikipedia is the online, collaborative version: anyone can write or edit an article, but contributors must stay neutral and cite reliable sources for every claim.","by":"James","title":"Real world:"},{"screen":"Publishing video on YouTube","src":"img/notes/n_sAANwlejqTQ.jpg","w":1000,"h":667,"alt":"A man in a black T-shirt holding a video camera and looking at its screen","cap":"A creator checks a shot on a handheld video camera. Publishing video on a sharing platform starts with recording good footage, then editing it and adding a clear title, description and thumbnail before uploading.","by":"Kyle Loftus","title":"Real world:"},{"screen":"Live streaming: setup and best practice","src":"img/notes/n_0O0gux4OZX4.jpg","w":1000,"h":667,"alt":"A professional video camera filming a group of musicians performing","cap":"A professional camera films musicians performing so the session can be streamed live. A reliable live stream depends on setup: stable internet, a good camera and microphone, and testing everything before going live.","by":"Jesus Loves Austin","title":"Real world:"},{"screen":"Benefits and limitations of online platforms","src":"img/notes/n_98MbUldcDJY.jpg","w":1000,"h":667,"alt":"An old brass weighing scale with two pans","cap":"A traditional weighing scale with two pans. Choosing an online platform means weighing its benefits, such as a large ready-made audience and ease of use, against limitations such as less control and platform rules.","by":"Piret Ilver","title":"Real world:"},{"screen":"Maintaining content on online platforms","src":"img/notes/n_PKcTuA_CRAo.jpg","w":1000,"h":667,"alt":"A gloved person pruning a green juniper bush with hand shears","cap":"A gardener prunes a bush to keep it healthy. Online content needs the same regular care: updating out-of-date information, fixing broken links, moderating comments and removing posts that no longer serve the audience.","by":"Crystal Jo","title":"Real world:"}],"M2U10":[{"screen":"What is content management?","src":"img/notes/n_Q9y3LRuuxmg.jpg","w":1000,"h":665,"alt":"A wooden card-file cabinet with rows of small labelled drawers","cap":"A cabinet of labelled drawers keeps every card where it can be found again. Content management does the same job for digital content, so the right people can find it, trust it and use it.","by":"Maksym Kaharlytskyi","title":"Real world:"},{"screen":"Types of digital content management and ECM","src":"img/notes/n_BEEyeib-am8.jpg","w":1000,"h":667,"alt":"Tall wooden bookshelves filled with books in a university library","cap":"Shelves in a university library hold collections of every kind. Enterprise Content Management works at a similar scale, handling all of an organisation's documents, records and media, while other types manage just one category of content.","by":"Trnava University","title":"Real world:"},{"screen":"Types of CMS: DMS, WCM, MCM and DAM","src":"img/notes/n_MTqaqBY6lfA.jpg","w":1000,"h":562,"alt":"A row of colourful ring binders standing on a shelf","cap":"Colour-coded binders keep different kinds of material apart. In the same way, each type of CMS specialises: a DMS for documents, a WCM for web pages, an MCM for mobile content and a DAM for images and media.","by":"Jonas Augustin","title":"Real world:"},{"screen":"Headless CMS: the head and the body","src":"img/notes/n_X_TYa6Nxu2A.jpg","w":1000,"h":667,"alt":"A desk with two laptops, a graphics tablet and a smartphone with colourful screens","cap":"A designer's desk holds several screens of different sizes. A headless CMS stores content once as the 'body', and sends it to whichever 'head' displays it: a website, an app or another device.","by":"Jakub Żerdzicki","title":"Real world:"},{"screen":"APIs and the one-story, four-heads case","src":"img/notes/n_9CR19q291ac.jpg","w":1000,"h":563,"alt":"A waiter taking an order from a group of friends at a café table","cap":"A waiter takes orders to the kitchen and brings the food back. An API works like this messenger: it carries a request to a system and returns the response, so one story can reach four different 'heads'.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Classifying CMS: open source, proprietary and SaaS","src":"img/notes/n_bqUZEAeWuok.jpg","w":1000,"h":667,"alt":"A hand holding house keys in front of a home's entrance","cap":"A hand holds the keys to a home. Choosing a CMS is like choosing housing: open source is like owning and maintaining your own house, proprietary is like a licensed property, and SaaS is like renting with maintenance included.","by":"Jakub Żerdzicki","title":"Real world:"},{"screen":"SaaS CMS and hosting choices","src":"img/notes/n_klWUhr-wPJ8.jpg","w":1000,"h":596,"alt":"Rows of black server racks in a data centre","cap":"Rows of servers in a data centre. A SaaS CMS bundles the software, hosting and support on machines like these in the cloud, so the customer pays a subscription instead of running servers.","by":"imgix","title":"Real world:"},{"screen":"Common CMS features and popular systems","src":"img/notes/n_2NuEzrmD2xQ.jpg","w":1000,"h":667,"alt":"A red multi-tool pocket knife with several tools folded out","cap":"A multi-tool pocket knife packs many tools into one handle. A CMS is similar, combining common features such as a visual editor, media library, user roles, templates and plug-ins in one system.","by":"Patrick","title":"Real world:"},{"screen":"Content management techniques and the content workflow","src":"img/notes/n_OXmym9cuaEY.jpg","w":1000,"h":786,"alt":"Hands holding three sticky notes labelled To Do, Doing and Done","cap":"Sticky notes labelled To Do, Doing and Done track work as it moves along. A content workflow does the same, taking each item through creating, editing, approving, publishing, archiving and updating.","by":"Eden Constantino","title":"Real world:"},{"screen":"Factors influencing trends in web publishing","src":"img/notes/n_aId-xYRTlEc.jpg","w":1000,"h":667,"alt":"Close-up of an old typewriter with a sheet of paper reading News","cap":"An old typewriter typing the word 'News' recalls how publishing used to work. Technology, economics, society, law and politics are among the factors that pushed news from typewriters to the web.","by":"Markus Winkler","title":"Real world:"},{"screen":"Impact on web publishing","src":"img/notes/n_wvlyUYpo_5k.jpg","w":1000,"h":668,"alt":"A large pile of folded newspapers stacked on top of each other","cap":"A stack of printed newspapers. The factors driving web publishing have changed how content is created, distributed, paid for and consumed, which is why many readers now get the news on screens rather than paper.","by":"Greg Bulla","title":"Real world:"},{"screen":"Emerging trends in web publishing","src":"img/notes/n_f0BJ6TXXtuM.jpg","w":1000,"h":563,"alt":"A smiling young woman wearing a virtual reality headset and reaching out with her hand","cap":"A young woman reaches out while wearing a virtual reality headset. Immersive formats such as VR and AR are among the emerging trends changing how digital content is published and experienced.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"More trends and developments in digital publishing","src":"img/notes/n_9TF54VdG0ws.jpg","w":1000,"h":667,"alt":"A small grey fabric smart speaker glowing on a white surface","cap":"A smart speaker answers spoken questions directly. Voice assistants, like AI search summaries, give users information without a click through to a website, which is part of the 'zero-click' challenge facing publishers.","by":"Kevin Bhagat","title":"Real world:"},{"screen":"Research tools for discovering and tracking trends","src":"img/notes/n_T69h1_YfR-w.jpg","w":1000,"h":668,"alt":"A woman looking through grey binoculars outdoors","cap":"A woman scans the distance through binoculars. Research tools such as search engines, analytics, trend reports and social media help publishers spot trends early and keep track of them.","by":"Chase Clark","title":"Real world:"}],"M3U1":[{"screen":"What is the mobile ecosystem?","src":"img/notes/n_1s1zWWELg3c.jpg","w":1000,"h":563,"alt":"Three young people sitting together with smartphones and coffee","cap":"Three friends sit together, each with a smartphone. Every phone links its owner to a wider mobile ecosystem of handset makers, networks, app developers, stores and regulators working together.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Carriers and telcos","src":"img/notes/n_pjW5WezrdJk.jpg","w":1000,"h":563,"alt":"Technician on a lift working on equipment at the top of a cell tower","cap":"A technician on a lift services equipment on a cell tower. Carriers and telcos build and maintain this infrastructure so that customers' calls, texts and mobile data can travel across the network.","by":"iStrfry , Marcus","title":"Real world:"},{"screen":"Consumers: behaviour, expectations and usage patterns","src":"img/notes/n_62EiTtKp9-0.jpg","w":1000,"h":667,"alt":"Two women at a bus stop looking at a smartphone together","cap":"Two women check a smartphone together while waiting at a bus stop. Consumers' habits, such as using phones on the move for travel information, shape what users expect from apps and services.","by":"Centre for Ageing Better","title":"Real world:"},{"screen":"The enabling environment: policy, regulators and developers","src":"img/notes/n_M6Yrvga15cU.jpg","w":1000,"h":667,"alt":"Parish Council building in Hanover, Jamaica","cap":"The Parish Council building in Hanover, Jamaica. Government bodies like this, together with regulators and policy makers, form the enabling environment that sets the rules for mobile networks, services and developers.","by":"Kemoi Brown","title":"Real world:"},{"screen":"Interdependence: how each player affects the others","src":"img/notes/n_QQndccmxOA0.jpg","w":1000,"h":637,"alt":"A long row of standing dominoes","cap":"A row of dominoes stands ready to fall. In the mobile ecosystem, players are interdependent: a change by one, such as a network outage or new store rule, knocks on to everyone else.","by":"Robert Stump","title":"Real world:"},{"screen":"The Caribbean mobile ecosystem: challenges and opportunities","src":"img/notes/n_SKV9kzTFjxY.jpg","w":1000,"h":750,"alt":"View of Sint Maarten from Sonesta Maho beach resort","cap":"A view of Sint Maarten from Sonesta Maho beach resort. Small island markets like ours face challenges such as limited scale and hurricane risk, but also opportunities in tourism and regional services.","by":"James Thomas","title":"Real world:"}],"M3U2":[{"screen":"Operating systems and platforms: the basics","src":"img/notes/n_bWni_SgHVpk.jpg","w":1000,"h":750,"alt":"Hand holding a smartphone showing its system settings screen","cap":"A hand holds a smartphone open at its system settings. The operating system manages the hardware, settings and apps, providing the platform that every mobile application runs on.","by":"Andrey Matveev","title":"Real world:"},{"screen":"Android, iOS and HarmonyOS compared","src":"img/notes/n_rIC8rWEe7cs.jpg","w":1000,"h":750,"alt":"Two smartphones side by side showing different app interfaces","cap":"Two smartphones sit side by side showing different interfaces. Comparing operating systems such as Android, iOS and HarmonyOS means looking at design, app stores, devices supported and market share.","by":"Andrey Matveev","title":"Real world:"},{"screen":"Development environments, app stores and revenue","src":"img/notes/n_6sAl6aQ4OWI.jpg","w":1000,"h":641,"alt":"Smartphone in front of computer monitors displaying code","cap":"A smartphone rests in front of monitors full of code. Developers write and test apps in development environments on computers before publishing them to app stores to earn revenue.","by":"Fotis Fotopoulos","title":"Real world:"},{"screen":"Smart devices and wearables","src":"img/notes/n_6KgixwY9Ebs.jpg","w":1000,"h":663,"alt":"Smartwatch worn on a person's left wrist","cap":"A smartwatch worn on the wrist. Wearables like this extend the mobile ecosystem beyond phones, tracking activity and showing notifications from a paired smartphone.","by":"Al Amin Mir","title":"Real world:"},{"screen":"The Internet of Things, sensors and embedded systems","src":"img/notes/n_vtg8tAdoWVQ.jpg","w":1000,"h":751,"alt":"Arduino Uno board wired to sensors on a breadboard","cap":"An Arduino board is wired to sensors on a breadboard. Small embedded systems like this collect readings and can send data to apps, which is the basic idea behind the Internet of Things.","by":"Vishnu Mohanan","title":"Real world:"},{"screen":"Native, web and cross-platform development","src":"img/notes/n_q-tCwIPpmRA.jpg","w":1000,"h":750,"alt":"Two white smartphones with multiple cameras side by side on an orange background","cap":"An iPhone and an Android phone side by side. Native apps are built separately for each operating system, while cross-platform tools use one codebase to reach both.","by":"Georgiy Lyamin","title":"Real world:"},{"screen":"Choosing a platform: audience, budget, time-to-market","src":"img/notes/n_hVfM3XPdBF8.jpg","w":1000,"h":639,"alt":"Passenger plane coming in to land low over the seashore","cap":"A passenger plane comes in to land over the seashore. An app for arriving visitors must suit their devices and needs, so audience, budget and time-to-market all shape which platform a developer chooses.","by":"Ramon Kagie","title":"Real world:"}],"M3U3":[{"screen":"The numbers: global and Caribbean statistics","src":"img/notes/n_q21XvpB7uQU.jpg","w":1000,"h":667,"alt":"Printed document showing bar charts and pie charts","cap":"A printed report shows bar and pie charts. Statistics on subscriptions, smartphone ownership and internet use help us compare the Caribbean mobile market with global figures.","by":"Cht Gsml","title":"Real world:"},{"screen":"Social and economic impact: banking, e-government, health","src":"img/notes/n_Xn5FbEM9564.jpg","w":1000,"h":667,"alt":"Customer paying with a smartphone at a shop counter beside a tablet","cap":"A customer pays with a smartphone at a shop counter. Mobile banking and payments are one way mobile technology has social and economic impact, alongside e-government and mobile health services.","by":"Blake Wisz","title":"Real world:"},{"screen":"Applications: agriculture, education, tourism, disasters","src":"img/notes/n_FBVXwQgALqg.jpg","w":1000,"h":563,"alt":"Man standing in a crop field looking at his mobile phone","cap":"A man checks his phone while standing in a field. Farmers can use mobile apps for weather forecasts, market prices and advice, one of many applications alongside education, tourism and disaster alerts.","by":"Rahul Dolai","title":"Real world:"},{"screen":"Content consumption vs content production","src":"img/notes/n_C5cbpx97MRI.jpg","w":1000,"h":563,"alt":"Young woman filming herself with a smartphone to record a vlog","cap":"A young woman films herself for a vlog. She is producing content, not just consuming it, which is the shift the region needs to make to benefit more from the mobile ecosystem.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Infrastructure: cables, 4G and 5G, and gaps","src":"img/notes/n_eVWWr6nmDf8.jpg","w":1000,"h":669,"alt":"Fibre optic cables plugged into a network switch","cap":"Fibre optic cables connect into a network switch. Fibre, including submarine cables linking the islands, carries the data that 4G and 5G networks deliver, and gaps in it limit coverage and speed.","by":"Kirill Sh","title":"Real world:"},{"screen":"Policy, security and ethical considerations","src":"img/notes/n_ah-HeguOe9k.jpg","w":1000,"h":563,"alt":"Smartphone screen displaying a padlock security icon","cap":"A smartphone shows a padlock security icon. Protecting users' data, preventing fraud and using personal information ethically are key policy and security concerns for mobile services.","by":"Dan Nelson","title":"Real world:"},{"screen":"The diaspora connection","src":"img/notes/n_3toEqCkUqEM.jpg","w":1000,"h":563,"alt":"Elderly couple smiling and waving at a smartphone during a video call","cap":"An elderly couple wave during a video call. Mobile apps help Caribbean families keep in touch with relatives overseas, and the diaspora also sends remittances and uses apps to stay connected to home.","by":"Vitaly Gariev","title":"Real world:"}],"M3U4":[{"screen":"Why build apps for local needs?","src":"img/notes/n_tyB4VfStCQI.jpg","w":1000,"h":751,"alt":"The Life Yard community space in downtown Kingston, Jamaica","cap":"The Life Yard community in downtown Kingston, Jamaica. Local communities have their own needs and culture, which is why apps designed locally can serve people better than imported ones.","by":"Nigel SB Photography","title":"Real world:"},{"screen":"Universal apps with a local twist","src":"img/notes/n_wGyHvtLcW_U.jpg","w":1000,"h":667,"alt":"White and blue minibus parked near a palm tree","cap":"A minibus parks beside a palm tree. Ride and transport apps are universal ideas, but a local twist, such as covering route taxis and minibuses, makes them work for Caribbean users.","by":"Rock Staar","title":"Real world:"},{"screen":"Social and cultural linkages","src":"img/notes/n_98t43MWNJdQ.jpg","w":1000,"h":828,"alt":"Masqueraders in colourful costumes at Carnaval 2024, Trinidad and Tobago","cap":"Masqueraders in colourful costumes at Trinidad and Tobago's Carnaval 2024. Apps for festival schedules, bands and music strengthen social and cultural links within the region and with the diaspora.","by":"Anton Acosta","title":"Real world:"},{"screen":"Economic benefits: jobs, entrepreneurship and export","src":"img/notes/n_8KeNG7-kqtU.jpg","w":1000,"h":667,"alt":"Delivery rider on a scooter checking his phone","cap":"A delivery rider checks his phone on a scooter. Local delivery apps create jobs and small-business opportunities, and successful apps can later be exported to other markets.","by":"Sushanta Rokka","title":"Real world:"},{"screen":"Case studies: Caribbean-developed apps","src":"img/notes/n_3NboWTtsV2k.jpg","w":1000,"h":667,"alt":"Street scene of a person making a living in Havana, Cuba","cap":"A person making a living on a street in Havana, Cuba. Case studies of Caribbean-developed apps show how local developers solve problems for people and small traders in their own communities.","by":"Nick Karvounis","title":"Real world:"},{"screen":"Social impact apps","src":"img/notes/n_C-Q64BTSvJ4.jpg","w":1000,"h":667,"alt":"Stacked cans of drinking water","cap":"Stacked cans of drinking water ready for an emergency. Social impact apps can help communities prepare for hurricanes, find relief supplies and share safety information.","by":"Beau Carpenter","title":"Real world:"},{"screen":"Writing an \"examine the benefits\" answer","src":"img/notes/n_s7rQVpRYWtY.jpg","w":1000,"h":563,"alt":"Over-the-shoulder view of a person writing with a pen","cap":"A student writes by hand with a pen. In an \"examine the benefits\" answer, set out each benefit clearly, explain it, and support it with a relevant local example.","by":"Ojus Jaiswal","title":"Real world:"}],"M3U5":[{"screen":"What is mobile user experience?","src":"img/notes/n_McXvj_1VSFM.jpg","w":1000,"h":667,"alt":"Man holding and using an iPhone outdoors","cap":"A man uses his phone outdoors. Mobile user experience is how easy, efficient and pleasant an app feels to use in real conditions like these.","by":"Mediamodifier","title":"Real world:"},{"screen":"Screen size, resolution and touch","src":"img/notes/n_q8U1YgBaRQk.jpg","w":1000,"h":667,"alt":"A person holding a white smartphone and touching the screen","cap":"A person taps a smartphone screen with a finger. Because fingers are less precise than a mouse pointer, mobile designs need large, well-spaced buttons and readable text on small screens.","by":"NordWood Themes","title":"Real world:"},{"screen":"Bandwidth, connectivity and data usage","src":"img/notes/n_MrHJOsmmKpI.jpg","w":1000,"h":563,"alt":"Man using a smartphone while sitting in a café","cap":"A man uses his smartphone in a café. Whether he is on fast Wi-Fi or slow mobile data affects load times, so good apps reduce data usage and handle weak connections gracefully.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Portability, context of use and device performance","src":"img/notes/n_MWKAobbb_Bk.jpg","w":1000,"h":800,"alt":"Person using a smartphone while travelling on public transport","cap":"A passenger uses a smartphone on public transport. Phones are used on the move, often one-handed and in short bursts, so apps must suit this context and run smoothly on the device.","by":"Kyle Hinkson","title":"Real world:"},{"screen":"Accessibility and inclusive design","src":"img/notes/n_SFP95g4WGFA.jpg","w":1000,"h":672,"alt":"Close-up of a person's hands using a smartphone","cap":"Close-up of hands using a smartphone. Accessible, inclusive design, such as adjustable text size, good colour contrast and screen-reader support, lets people of all abilities use an app.","by":"Sherise Van Dyk","title":"Real world:"},{"screen":"Physical environment and user profile","src":"img/notes/n_eoLZkDYES54.jpg","w":1000,"h":667,"alt":"Hand holding a smartphone up outdoors to take a photograph","cap":"A phone is held up outdoors to take a photo. Bright sunlight, noise and movement are part of the physical environment, and together with the user's profile they affect how an app is experienced.","by":"Clint McKoy","title":"Real world:"},{"screen":"Factor, effect, strategy: exam summary","src":"img/notes/n_oXV3bzR7jxI.jpg","w":1000,"h":667,"alt":"Person writing on paper with a pencil","cap":"A person writes notes with a pencil. A clear exam answer names the factor, explains its effect on the user experience, then gives a design strategy to deal with it.","by":"Ben Mullins","title":"Real world:"}],"M3U6":[{"screen":"Conceptualisation: purpose, users, features and MVP","src":"img/notes/n_ETRPjvb0KM0.jpg","w":1000,"h":667,"alt":"Brainstorming sticky notes stuck on a wall","cap":"Sticky notes from a brainstorming session cover a wall. Conceptualisation starts like this: agree the app's purpose, target users and key features, then choose a minimum viable product to build first.","by":"Patrick Perkins","title":"Real world:"},{"screen":"Recap: wireframes, mockups and prototypes for apps","src":"img/notes/n_s9CC2SKySJM.jpg","w":1000,"h":667,"alt":"Designer sketching wireframes on paper at a desk","cap":"A designer sketches wireframes by hand. Wireframes plan layout, mockups add visual detail and prototypes let people try the app before any code is written.","by":"Unseen Studio","title":"Real world:"},{"screen":"Wireframing on paper and in Figma or Balsamiq","src":"img/notes/n_Jz6ol2vASgw.jpg","w":1000,"h":667,"alt":"A pink pencil on grid paper with hand-drawn wireframe sketches","cap":"Wireframe sketches drawn on grid paper. Low-fidelity paper wireframes are fast to make and easy to redraw, which suits exploring app screen ideas before moving to Figma or Balsamiq.","by":"Vitalii Abakumov","title":"Real world:"},{"screen":"User flows and clickable prototypes","src":"img/notes/n_w00FkE6e8zE.jpg","w":1000,"h":667,"alt":"Team arranging sticky notes on a board to map a user journey","cap":"A team maps a user journey with sticky notes. Planning each step a user takes through an app produces a user flow, which can then be linked into a clickable prototype.","by":"UX Indonesia","title":"Real world:"},{"screen":"Native development: Android Studio and Xcode","src":"img/notes/n_kQIdjLbCghA.jpg","w":1000,"h":667,"alt":"Developer working at a desk with two screens showing a design tool","cap":"A developer works across two screens. Native apps are built in official environments, Android Studio for Android and Xcode for iOS, which give full access to each device's features.","by":"Olumuyiwa Sobowale","title":"Real world:"},{"screen":"No-code and low-code app builders","src":"img/notes/n_kaI1tCAXrtI.jpg","w":1000,"h":667,"alt":"Friends building with toy blocks beside a laptop in an office","cap":"Friends build with toy blocks beside a laptop. No-code and low-code builders work in a similar way, letting you assemble an app from ready-made blocks instead of writing every line of code.","by":"Hardingferrent","title":"Real world:"},{"screen":"MIT App Inventor: a guided tour","src":"img/notes/n_hLvQ4-QEBAE.jpg","w":1000,"h":667,"alt":"Child using a tablet for visual block-based programming","cap":"A child uses a tablet for visual programming. MIT App Inventor uses the same idea, with drag-and-drop blocks for app logic and a designer view for laying out screens.","by":"Robo Wunderkind","title":"Real world:"},{"screen":"Step-by-step build: the Johnny Cake Counter","src":"img/notes/n_ZWmq2rn1bKQ.jpg","w":667,"h":1000,"alt":"Johnny cakes frying in a pan on a coal pot","cap":"West Indian johnny cakes being fried on a coal pot. The Johnny Cake Counter project is a simple first app with buttons and a label that keep count, just like tallying a batch of these.","by":"Karl Callwood","title":"Real world:"},{"screen":"Testing, debugging, feedback and refinement","src":"img/notes/n_FCHlYvR5gJI.jpg","w":1000,"h":667,"alt":"Man programming on a laptop","cap":"A man works through code on a laptop. Testing finds errors, debugging fixes them, and feedback from real users guides refinement until the app works reliably.","by":"Danial Igdery","title":"Real world:"},{"screen":"Online resources, communities and exam practice","src":"img/notes/n_Im_cQ6hQo10.jpg","w":1000,"h":667,"alt":"Two people working on computer code at monitors in a bright office","cap":"Two developers work on code together. No developer knows everything, so they rely on official documentation, Stack Overflow and GitHub communities to solve problems.","by":"Compagnons","title":"Real world:"}],"M3U7":[{"screen":"How apps reach users: distribution models","src":"img/notes/n_PfItlvrPX2U.jpg","w":1000,"h":667,"alt":"Smartphone screen filled with colourful app icons","cap":"A smartphone shows a screen of colourful app icons. Each one reached the user through a distribution model, such as an official app store, a web app or direct enterprise distribution.","by":"Georgiy Lyamin","title":"Real world:"},{"screen":"Publishing to the stores, and the risks of sideloading","src":"img/notes/n_vXInUOv1n84.jpg","w":1000,"h":667,"alt":"Black Android smartphone lying on a surface","cap":"An Android smartphone. Publishing to official stores means meeting review guidelines, whereas sideloading installs apps from outside the store and can expose users to malware.","by":"Roman Synkevych","title":"Real world:"},{"screen":"The user journey: discover to retain","src":"img/notes/n_wG6eFc8WuI4.jpg","w":1000,"h":563,"alt":"A group of four adults looking at a smartphone together in a cafe","cap":"Friends share something on a phone in a cafe. Word of mouth like this is one way users discover an app, before they test it, read reviews, download and keep using it.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"App Store Optimisation (ASO)","src":"img/notes/n_apWKtH5x0ME.jpg","w":1000,"h":667,"alt":"Phone home screen showing a grid of app icons","cap":"A home screen crowded with app icons. App Store Optimisation uses a clear name, keywords, a strong icon, screenshots and good reviews to help an app stand out in store searches.","by":"Georgiy Lyamin","title":"Real world:"},{"screen":"Marketing channels for apps","src":"img/notes/n_pP3qyl9M6dI.jpg","w":1000,"h":563,"alt":"Two women photographing coffee cups with a smartphone at a cafe","cap":"Two friends photograph their coffee with a phone. Everyday posts like this show how social media content spreads, which is why apps use organic posts, influencers and paid social ads to reach new users.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Beta testing and building a community before launch","src":"img/notes/n_QckxruozjRg.jpg","w":1000,"h":667,"alt":"Group of people sitting together around a laptop","cap":"A group gathers round a laptop to try something together. Beta testers give feedback before launch and become early supporters who help build a community around the app.","by":"Annie Spratt","title":"Real world:"},{"screen":"Planning and measuring an app marketing campaign","src":"img/notes/n_AT77Q0Njnt0.jpg","w":1000,"h":667,"alt":"Hand drawing a rising goal chart with a pen on paper","cap":"A hand charts goals on paper. A marketing campaign needs clear targets, such as downloads or active users, and measurements to check whether those targets are being met.","by":"Isaac Smith","title":"Real world:"}],"M3U8":[{"screen":"What is a revenue model?","src":"img/notes/n_SoqG9RWd_FA.jpg","w":1000,"h":667,"alt":"Coins collected in a glass money jar","cap":"Coins collect in a money jar. A revenue model is the plan for how an app will earn money, whether from users, advertisers or other sources.","by":"Nick Fewings","title":"Real world:"},{"screen":"Freemium and in-app purchases","src":"img/notes/n_JCjapEdFl0I.jpg","w":1000,"h":563,"alt":"Hands holding a smartphone sideways while playing a game","cap":"Hands hold a phone sideways to play a game. Many games are freemium: free to download, earning money through in-app purchases such as extra levels or items.","by":"Thomas Kinto","title":"Real world:"},{"screen":"In-app advertising and subscriptions","src":"img/notes/n_rl6aomPDKl8.jpg","w":1000,"h":667,"alt":"A person playing a video game on a smartphone","cap":"A person plays a game on a phone. Many free mobile games earn money from banner, interstitial and rewarded video ads, or by offering subscriptions and paid extras.","by":"Pandhuya Niking","title":"Real world:"},{"screen":"Developer fees, licensing and white-label apps","src":"img/notes/n_pAgCpLoYXdQ.jpg","w":1000,"h":667,"alt":"Laptop showing a weather API integration project","cap":"A laptop shows a weather API integration project. Developers can earn by charging fees, licensing code like this to others, or building white-label apps that clients rebrand as their own.","by":"Fahim Muntashir","title":"Real world:"},{"screen":"Open source and community-supported models","src":"img/notes/n_vdXMSiX-n6M.jpg","w":1000,"h":750,"alt":"Four people sitting together watching a laptop screen","cap":"Four people work together round a laptop. Open source apps are built by communities who share code freely, often funded by donations, sponsorship or paid support.","by":"Mimi Thian","title":"Real world:"},{"screen":"Civic, charity and social good apps","src":"img/notes/n_K0E6E0a0R3A.jpg","w":1000,"h":667,"alt":"Hands holding coins and a note reading make a change","cap":"Hands offer coins with a note reading \"make a change\". Civic and charity apps focus on social good, funded by donations, grants or government rather than by profit.","by":"Katt Yukawa","title":"Real world:"},{"screen":"Evaluating and choosing a revenue model","src":"img/notes/n_joqWSI9u_XM.jpg","w":1000,"h":668,"alt":"A glass jar filled with coins and a small plant","cap":"A jar of saved coins with a growing plant. Choosing a revenue model means weighing user value, affordability and long-term sustainability, so an app can keep earning without exploiting its users.","by":"Towfiqu barbhuiya","title":"Real world:"}],"M3U9":[{"screen":"Why trends happen: the driving factors","src":"img/notes/n_DsmDqiYduaU.jpg","w":1000,"h":608,"alt":"Black Android phone showing its home screen","cap":"An Android phone's home screen. Trends happen because of driving factors such as new technology, falling device prices, changing user needs, competition and regulation.","by":"The Average Tech Guy","title":"Real world:"},{"screen":"Emerging trends 1: AI, payments, 5G, edge and IoT","src":"img/notes/n_Q6uqw_Hjye8.jpg","w":1000,"h":667,"alt":"Smartphone being used to scan a QR code for payment","cap":"A smartphone scans a QR code to pay. Mobile payments are a fast-growing trend, along with AI features, 5G, edge computing and the Internet of Things.","by":"Markus Winkler","title":"Real world:"},{"screen":"Emerging trends 2: AR, VR, wearables, foldables, PWAs and low-code","src":"img/notes/n_AHCmAX0k_J4.jpg","w":1000,"h":514,"alt":"A man wearing a virtual reality headset","cap":"A man uses a virtual reality headset. VR places the user in a fully computer-generated environment, useful for training and immersive tourism previews, although headsets remain costly.","by":"Minh Pham","title":"Real world:"},{"screen":"Super apps and the consolidation of services","src":"img/notes/n_gUIJ0YszPig.jpg","w":1000,"h":667,"alt":"Team chat app shown on a desktop computer and a smartphone","cap":"A chat app runs on both a desktop and a phone. Super apps grow from services like messaging by adding payments, shopping and transport, bringing many services into one app.","by":"Austin Distel","title":"Real world:"},{"screen":"Cybersecurity, privacy, data laws and accessibility","src":"img/notes/n_Uw_8vSroCSc.jpg","w":1000,"h":563,"alt":"Finger touching the fingerprint sensor on a phone","cap":"A finger uses a phone's fingerprint sensor. Biometric security protects personal data, but apps must also follow privacy and data protection laws and stay accessible to all users.","by":"Onur Binay","title":"Real world:"},{"screen":"Caribbean trends: mobile money, digital ID and e-government","src":"img/notes/n_kHMiTbqI5QU.jpg","w":1000,"h":667,"alt":"Smartphone screen displaying a QR code","cap":"A smartphone displays a QR code. Mobile money, digital ID and e-government services increasingly rely on codes and apps like this across the Caribbean.","by":"Markus Winkler","title":"Real world:"},{"screen":"Research tools for tracking mobile trends","src":"img/notes/n_qwtCeJ5cLYs.jpg","w":1000,"h":720,"alt":"Laptop screen showing a data reporting dashboard","cap":"A laptop displays a data dashboard. Market reports, analytics dashboards and industry statistics are research tools that help track how mobile trends change over time.","by":"Stephen Dawson","title":"Real world:"}],"M1U2":[{"screen":"The elements of visual design","kind":"example","title":"Line: a pier that pulls the eye to the horizon","tag":"Line","html":"<p>The broken concrete pier is a set of strong <b>leading lines</b>. Its edges start wide at the bottom of the frame and converge towards the island on the horizon, so the eye travels from the foreground straight to the distance.</p><p>The palette is almost all greys and near-black (<span class=\"hexchip\" style=\"--c:#79867B\"><i></i>#79867B</span>, <span class=\"hexchip\" style=\"--c:#070A09\"><i></i>#070A09</span>): with so little colour, line and value do all the work.</p>","q":"Find a road, fence, railing or row of palm trees near your school. Photograph it so the lines lead to one point of interest.","wide":false,"pal":[["#79867b",36,"grey"],["#57625c",25,"grey"],["#070a09",21,"near black"],["#9ba490",7,"grey"],["#4b4736",7,"dark muted yellow-orange"],["#8e8058",3,"muted yellow-orange"]],"w":1000,"h":714,"by":"Ocho Artex Media","alt":"A crumbling concrete pier stretches into the sea","cap":"Line: a pier that pulls the eye to the horizon","src":"img/notes/c_hz8sbSg2nU0.jpg"},{"screen":"The elements of visual design","kind":"example","title":"Texture and colour: a weathered painted door","tag":"Texture","html":"<p>Peeling turquoise paint over older green layers, with an orange door beside it: you can almost <i>feel</i> the rough surface. This is <b>visual texture</b>, the look of a surface in a flat image.</p><p>The orange (<span class=\"hexchip\" style=\"--c:#F67635\"><i></i>#F67635</span>) sits almost opposite the turquoise (<span class=\"hexchip\" style=\"--c:#449AB3\"><i></i>#449AB3</span>) on the colour wheel, so the two doors make each other look more intense. Designers use textures like this as backgrounds for posters and album covers to add age and character.</p>","q":"Name the element of design that makes this photo feel old, and the colour relationship that makes it eye-catching.","wide":false,"pal":[["#449ab3",27,"cyan"],["#73a384",25,"muted green"],["#f67635",15,"orange"],["#0b809b",10,"cyan"],["#7fa356",1,"green"]],"w":1000,"h":667,"by":"Markus Voetter","alt":"closeup view of blue and green wooden door","cap":"Texture and colour: a weathered painted door","src":"img/notes/c_lcwRFAX7ox8.jpg"},{"screen":"The elements of visual design","kind":"example","title":"Space: one small sail in a lot of emptiness","tag":"Space","html":"<p>The boat takes up less than 1% of the photo; the rest is calm sea and pale sky. That large area of <b>negative space</b> is what makes the tiny sail impossible to miss.</p><p>The palette is one hue, blue, from a pale sky tint (<span class=\"hexchip\" style=\"--c:#B7C0D1\"><i></i>#B7C0D1</span>) to deep sea shades (<span class=\"hexchip\" style=\"--c:#163A63\"><i></i>#163A63</span>). Calm, empty space with cool colour reads as peaceful: ideal for a tourism or wellness brand.</p>","q":"Sketch a poster layout for a Sint Maarten sailing regatta that uses at least 60% negative space.","wide":false,"pal":[["#b7c0d1",54,"light muted blue"],["#315d87",39,"blue"],["#163a63",6,"dark blue"],["#688bb1",1,"blue"]],"w":667,"h":1000,"by":"Thomas K","alt":"A lone sailboat navigates the vast blue ocean","cap":"Space: one small sail in a lot of emptiness","src":"img/notes/c_MHVJY4-mxEQ.jpg"},{"screen":"The colour wheel: primary, secondary and tertiary","kind":"example","title":"Primary colours in your pencil case","tag":"Primary","html":"<p>Three of these crayons are the traditional painter's primaries: <b>red</b> (<span class=\"hexchip\" style=\"--c:#D84C42\"><i></i>#D84C42</span>), <b>yellow</b> (<span class=\"hexchip\" style=\"--c:#CA8F27\"><i></i>#CA8F27</span>) and <b>blue</b> (<span class=\"hexchip\" style=\"--c:#183C64\"><i></i>#183C64</span>). In the RYB model they cannot be mixed from other paints. The fourth crayon is green, a <b>secondary</b> colour made from blue plus yellow.</p><p>Notice that the real crayon colours are not perfectly pure: the yellow leans towards orange and the blue is quite dark. Real-world colours always sit somewhere <i>near</i> a point on the wheel.</p>","q":"Which two of these crayons would you layer to make green? Which pair would make orange?","wide":false,"pal":[["#183c64",2,"dark blue"],["#ca8f27",2,"orange"],["#337e6e",1,"teal"],["#d84c42",1,"red"]],"w":1000,"h":668,"by":"Aisling Tempany","alt":"Four colorful crayons arranged in a cross on white","cap":"Primary colours in your pencil case","src":"img/notes/c_2BSKhC5HhRM.jpg"},{"screen":"The colour wheel: primary, secondary and tertiary","kind":"example","title":"Tertiary colours on the Willemstad waterfront, Curaçao","tag":"Tertiary","html":"<p>Curaçao's famous waterfront shows how a whole city can work as a colour wheel. Between the pure hues you find <b>tertiary</b> colours: red-orange roofs, yellow-orange façades, blue-green (teal) and red-violet (pink) buildings.</p><p>The measured swatches show the dominant blues of sea and sky (<span class=\"hexchip\" style=\"--c:#457CAE\"><i></i>#457CAE</span>, <span class=\"hexchip\" style=\"--c:#2E4B70\"><i></i>#2E4B70</span>) with the warm façade colours (<span class=\"hexchip\" style=\"--c:#E9C3B0\"><i></i>#E9C3B0</span>, <span class=\"hexchip\" style=\"--c:#B68668\"><i></i>#B68668</span>) as a smaller band: a natural blue-orange contrast.</p>","q":"Name three tertiary colours you can see in the photo and the primary and secondary colour that make each one.","wide":false,"pal":[["#457cae",39,"blue"],["#2e4b70",23,"blue"],["#e9c3b0",4,"light orange"],["#752922",3,"dark red"],["#b68668",3,"orange"]],"w":1000,"h":667,"by":"Ulf Meyer","alt":"Colorful buildings line a waterfront under a blue sky","cap":"Tertiary colours on the Willemstad waterfront, Curaçao","src":"img/notes/c_CNvfGmcebgw.jpg"},{"screen":"The colour wheel: primary, secondary and tertiary","kind":"example","title":"Mixing new colours by hand","tag":"Mixing","html":"<p>Each well in this palette holds a colour made by mixing: pastel pink, mint, sky blue and lilac are all <b>tints</b> (a hue plus white). This is the RYB, subtractive way of making new colours.</p><p>Digital tools do the same job with numbers: in GIMP or Canva you build a new colour by adjusting hue, saturation and lightness, then save its hex code so you can use exactly the same colour again.</p>","q":null,"wide":false,"pal":[["#ece8dd",24,"light muted yellow-orange"],["#603115",23,"dark orange"],["#8d4d27",20,"orange"],["#a67853",11,"orange"],["#be9d76",4,"orange"],["#d29137",2,"orange"]],"w":1000,"h":667,"by":"Jonathan Borba","alt":"Hands mixing colorful paints on a palette","cap":"Mixing new colours by hand","src":"img/notes/c_8iS2kIjWm4g.jpg"},{"screen":"Colour harmony rules","kind":"example","title":"Complementary: an orange boat on turquoise water","tag":"Complementary","html":"<p>Blue-green water (<span class=\"hexchip\" style=\"--c:#81A4A3\"><i></i>#81A4A3</span>) and an orange hull (<span class=\"hexchip\" style=\"--c:#E7622B\"><i></i>#E7622B</span>) sit opposite each other on the wheel. Because they are complements, each makes the other look more vivid: this is <b>simultaneous contrast</b>.</p><p>Notice the proportions: the orange covers only about one-eighth of the image, the cool water and sky the rest. One dominant hue plus a small complementary accent is the safest way to use this scheme.</p>","q":"Design a call-to-action button for a dive-shop website with a turquoise background. What colour should the button be, and why?","wide":true,"pal":[["#6a8d7b",37,"muted green"],["#81a4a3",23,"muted teal"],["#e7622b",12,"orange"],["#456086",11,"blue"]],"w":1000,"h":750,"by":"Bernd Dittrich","alt":"Orange boat prow on clear turquoise water","cap":"Complementary: an orange boat on turquoise water","src":"img/notes/c__6DIhL6JQHA.jpg"},{"screen":"Colour harmony rules","kind":"example","title":"Complementary: a red hibiscus on green leaves","tag":"Complementary","html":"<p>The hibiscus, a flower seen in gardens across the Caribbean, shows red (<span class=\"hexchip\" style=\"--c:#E22C45\"><i></i>#E22C45</span>) against its complement, green (<span class=\"hexchip\" style=\"--c:#59772C\"><i></i>#59772C</span>). The red petals jump forward and the leaves fall back.</p><p><b>Warning for designers:</b> red and green look very different to most people, but for many people with red-green colour blindness they can look similar. Never rely on red versus green alone to show meaning, such as \"wrong\" and \"right\".</p>","q":null,"wide":false,"pal":[["#30342c",50,"charcoal"],["#e22c45",14,"red"],["#59772c",6,"yellow-green"],["#f85881",3,"pink-red"]],"w":1000,"h":667,"by":"Mufid Majnun","alt":"a red flower with green leaves in the background","cap":"Complementary: a red hibiscus on green leaves","src":"img/notes/c_NktB6fR8ulk.jpg"},{"screen":"Colour harmony rules","kind":"example","title":"Complementary: a violet pansy on yellow","tag":"Complementary","html":"<p>Yellow (<span class=\"hexchip\" style=\"--c:#E1B801\"><i></i>#E1B801</span>) and violet (<span class=\"hexchip\" style=\"--c:#521E57\"><i></i>#521E57</span>) are complements. Here the photographer placed one small violet flower on a huge yellow field: over 90% yellow, under 10% violet, and the flower still dominates.</p><p>This is a lesson in <b>proportion</b>: a small amount of a complementary colour creates a strong focal point.</p>","q":null,"wide":false,"pal":[["#e1b801",91,"yellow-orange"],["#521e57",5,"dark magenta"],["#7d5075",2,"muted magenta"]],"w":667,"h":1000,"by":"Daniele Levis Pelusi","alt":"purple flower on yellow background","cap":"Complementary: a violet pansy on yellow","src":"img/notes/c_Ds_F67g60g4.jpg"},{"screen":"Colour harmony rules","kind":"example","title":"Analogous: a waterfall in a green forest","tag":"Analogous","html":"<p>Every swatch here is a neighbour on the colour wheel: dark olive, yellow-green and yellow (<span class=\"hexchip\" style=\"--c:#424E12\"><i></i>#424E12</span>, <span class=\"hexchip\" style=\"--c:#8F9520\"><i></i>#8F9520</span>). <b>Analogous</b> colours share a common hue, so the image feels calm and unified, just like a walk through a rainforest such as those in Dominica or El Yunque in Puerto Rico.</p><p>The risk is sameness: the designer gets contrast from <b>value</b> (very dark shadows against light leaves) instead of from hue.</p>","q":null,"wide":false,"pal":[["#212c11",68,"near black"],["#424e12",14,"dark yellow-green"],["#636f12",11,"dark yellow-green"],["#8f9520",4,"yellow"],["#aaae34",3,"yellow"]],"w":1000,"h":667,"by":"Joshua Woroniecki","alt":"a small waterfall in the middle of a forest","cap":"Analogous: a waterfall in a green forest","src":"img/notes/c_AFWSdP8Ntaw.jpg"},{"screen":"Colour harmony rules","kind":"example","title":"Analogous: an Aruba sunset","tag":"Analogous","html":"<p>The sky over Aruba runs through yellow-orange (<span class=\"hexchip\" style=\"--c:#FEC84C\"><i></i>#FEC84C</span>), orange (<span class=\"hexchip\" style=\"--c:#E9A03C\"><i></i>#E9A03C</span>) and deep orange (<span class=\"hexchip\" style=\"--c:#C98434\"><i></i>#C98434</span>): three neighbouring warm hues. Analogous warm palettes feel inviting and energetic, which is why so many Caribbean hotel and festival brands use them.</p><p>The dark teal sea (<span class=\"hexchip\" style=\"--c:#1A3535\"><i></i>#1A3535</span>) adds a cool contrast at the bottom, so the composition is not flat.</p>","q":null,"wide":false,"pal":[["#1a3535",52,"dark teal"],["#fec84c",23,"yellow-orange"],["#e9a03c",13,"orange"],["#c98434",6,"orange"]],"w":1000,"h":667,"by":"Lex Melony","alt":"sun setting over the ocean","cap":"Analogous: an Aruba sunset","src":"img/notes/c__idYbIGUoJk.jpg"},{"screen":"Colour harmony rules","kind":"example","title":"Split-complementary: teal sky, orange walls","tag":"Split-complementary","html":"<p>The teal-blue sky (<span class=\"hexchip\" style=\"--c:#296272\"><i></i>#296272</span>) is the key colour. Instead of pure orange, its complement, the building shows a range of oranges from yellow-orange (<span class=\"hexchip\" style=\"--c:#DDA773\"><i></i>#DDA773</span>) to red-orange (<span class=\"hexchip\" style=\"--c:#C56D2D\"><i></i>#C56D2D</span>): the two hues either side of the complement.</p><p>A split-complementary scheme keeps the energy of complementary colours but feels less harsh, which is why it is a good choice for beginners.</p>","q":null,"wide":false,"pal":[["#296272",45,"cyan"],["#d98d4e",22,"orange"],["#dda773",8,"orange"],["#c56d2d",7,"orange"]],"w":667,"h":1000,"by":"Bikash Guragai","alt":"A modern orange building with angled yellow window frames against a clear blue sky","cap":"Split-complementary: teal sky, orange walls","src":"img/notes/c_K-2O9kvRnrg.jpg"},{"screen":"Colour harmony rules","kind":"example","title":"Tetradic: painted buildings in Oranjestad, Aruba","tag":"Tetradic","html":"<p>Four façades: light blue, pink, white with blue trim and yellow, plus green trees. Pink and green, blue and yellow-orange: that is <b>two complementary pairs</b>, the definition of a tetradic (rectangle) scheme.</p><p>It works because the sky blue (<span class=\"hexchip\" style=\"--c:#ABCFF3\"><i></i>#ABCFF3</span>) dominates and the other colours are spread out in smaller areas. If every colour were equal in size the street would look chaotic.</p>","q":"Pick one Caribbean town you know. Which four colours would you use for a tetradic tourism poster, and which one would dominate?","wide":true,"pal":[["#abcff3",28,"light blue"],["#a79110",6,"yellow-orange"],["#3172a1",3,"blue"],["#a8566c",1,"pink-red"]],"w":1000,"h":704,"by":"Jamie Tudor","alt":"a row of brightly colored houses on a street","cap":"Tetradic: painted buildings in Oranjestad, Aruba","src":"img/notes/c_EUxtOZX3chs.jpg"},{"screen":"Tints, shades, tones and gradients","kind":"example","title":"Tints: pastel façades in Havana, Cuba","tag":"Tints","html":"<p>Soft yellow, mint, peach and powder blue walls: these are <b>tints</b>, pure hues lightened with white. Tints feel friendly, airy and nostalgic.</p><p>Sun and age have also greyed many of the walls into <b>tones</b> (<span class=\"hexchip\" style=\"--c:#8C7A5A\"><i></i>#8C7A5A</span>, <span class=\"hexchip\" style=\"--c:#BD8B46\"><i></i>#BD8B46</span>), which is why the street looks gentle rather than loud.</p>","q":null,"wide":false,"pal":[["#8c7a5a",27,"muted orange"],["#aa9e81",11,"muted yellow-orange"],["#bd8b46",9,"orange"],["#2254a9",3,"blue"],["#4ea082",1,"teal"]],"w":1000,"h":667,"by":"Alex G","alt":"Old, colorful buildings flank a street with vintage cars","cap":"Tints: pastel façades in Havana, Cuba","src":"img/notes/c_H144zvyJ4eo.jpg"},{"screen":"Tints, shades, tones and gradients","kind":"example","title":"Shades: looking up through a forest canopy","tag":"Shades","html":"<p>The leaves run from a bright yellow-green into deep <b>shades</b> of green (<span class=\"hexchip\" style=\"--c:#223909\"><i></i>#223909</span>), the pure hue mixed with black. Shades create depth: the darkest greens seem to sit behind the lighter ones.</p><p>A designer could build a whole eco-tourism palette from this one photo by picking a dark shade for text, a mid green for buttons and white for the background.</p>","q":null,"wide":false,"pal":[["#223909",45,"dark green"],["#405d0e",21,"dark yellow-green"],["#5c6942",11,"muted yellow-green"],["#eaeced",7,"near white"]],"w":1000,"h":665,"by":"Trac Vu","alt":"Looking up through lush green forest canopy","cap":"Shades: looking up through a forest canopy","src":"img/notes/c_KJ407bjtcHU.jpg"},{"screen":"Tints, shades, tones and gradients","kind":"example","title":"Tones: misty mountains","tag":"Tones","html":"<p>Mist adds grey to every colour, so the blues of the hills become muted <b>tones</b> (<span class=\"hexchip\" style=\"--c:#3D4D58\"><i></i>#3D4D58</span>, <span class=\"hexchip\" style=\"--c:#576975\"><i></i>#576975</span>, <span class=\"hexchip\" style=\"--c:#7D8F9B\"><i></i>#7D8F9B</span>). The image is calm and quiet, and the colours recede.</p><p>Tones are useful for large background areas in a website or app because they do not compete with the content on top of them.</p>","q":null,"wide":false,"pal":[["#cfd1d0",43,"off-white"],["#131c20",17,"near black"],["#3d4d58",15,"dark muted blue"],["#576975",13,"muted blue"],["#7d8f9b",8,"muted blue"],["#27333b",4,"dark muted blue"]],"w":1000,"h":667,"by":"Leandro De Torres","alt":"Hazy mountain range with small village nestled below","cap":"Tones: misty mountains","src":"img/notes/c_p5pH8YfO7MY.jpg"},{"screen":"Tints, shades, tones and gradients","kind":"example","title":"Gradient: shallow to deep water, Bimini, Bahamas","tag":"Gradient","html":"<p>From above, the sea changes smoothly from bright turquoise over sand (<span class=\"hexchip\" style=\"--c:#05C9C4\"><i></i>#05C9C4</span>) to deeper teal and blue (<span class=\"hexchip\" style=\"--c:#0981A4\"><i></i>#0981A4</span>) as the water deepens. Nature has made a <b>gradient</b>: a gradual change from one colour to another.</p><p>The swatches here are arranged in order from light to dark, like the colour stops a designer would set in a gradient tool.</p>","q":null,"wide":true,"pal":[["#05c9c4",18,"teal"],["#3eafb9",8,"teal"],["#0981a4",21,"cyan"],["#057566",10,"dark teal"]],"w":1000,"h":562,"by":"Ricky Beron","alt":"An aerial view of the ocean with boats in the water","cap":"Gradient: shallow to deep water, Bimini, Bahamas","src":"img/notes/c_pB1iUlAOkV8.jpg"},{"screen":"Tints, shades, tones and gradients","kind":"example","title":"Gradient: a dawn sky","tag":"Gradient","html":"<p>This sky moves from blue at the top through pink to orange at the horizon: a natural <b>linear gradient</b>. Notice that blue and orange are complements, but the gradient passes through soft pinks in between, so the change feels smooth.</p><p>To recreate it, set the gradient tool's first stop to <span class=\"hexchip\" style=\"--c:#729AAE\"><i></i>#729AAE</span> and the last to <span class=\"hexchip\" style=\"--c:#FE9427\"><i></i>#FE9427</span>, then add a middle stop around <span class=\"hexchip\" style=\"--c:#D7A294\"><i></i>#D7A294</span>.</p>","q":null,"wide":false,"pal":[["#729aae",32,"muted blue"],["#3e90ab",11,"cyan"],["#d7a294",17,"red"],["#fda059",16,"orange"],["#fe9427",5,"orange"]],"w":667,"h":1000,"by":"Dave Hoefler","alt":"A smooth gradient shifting from soft blue to warm orange","cap":"Gradient: a dawn sky","src":"img/notes/c_PEkfSAxeplg.jpg"},{"screen":"Tints, shades, tones and gradients","kind":"example","title":"Monochromatic: a violet King costume in Port of Spain","tag":"Monochromatic","html":"<p>This Trinidad Carnival costume is built almost entirely from one hue, violet, used in pale tints (<span class=\"hexchip\" style=\"--c:#A493C4\"><i></i>#A493C4</span>), mid tones (<span class=\"hexchip\" style=\"--c:#7759B3\"><i></i>#7759B3</span>) and deep shades (<span class=\"hexchip\" style=\"--c:#261682\"><i></i>#261682</span>). That is a <b>monochromatic</b> scheme.</p><p>Even with one hue the costume is dramatic, because the designer used very light and very dark values side by side and added silver.</p>","q":null,"wide":true,"pal":[["#a493c4",13,"muted violet"],["#7759b3",5,"violet"],["#4e31a5",3,"violet"],["#261682",2,"dark violet"],["#833088",1,"magenta"]],"w":1000,"h":664,"by":"Holger Woizick","alt":"a woman in a purple costume with feathers on her head","cap":"Monochromatic: a violet King costume in Port of Spain","src":"img/notes/c_78z3qaiYN8I.jpg"},{"screen":"Colour mixing: RGB, CMYK, hex codes and new colours","kind":"example","title":"RGB: a screen under a macro lens","tag":"RGB (additive)","html":"<p>Zoom right into any phone or laptop screen and the picture breaks down into tiny <b>red, green and blue sub-pixels</b>. Each one glows at a brightness from 0 to 255.</p><p>Your eye blends neighbouring sub-pixels: full red plus full green looks yellow, all three at full brightness look white. A hex code such as <span class=\"hexchip\" style=\"--c:#86D64D\"><i></i>#86D64D</span> is just these three values written in base 16: two digits for red, two for green, two for blue.</p>","q":null,"wide":true,"pal":[["#360d0e",9,"dark red"],["#96341f",6,"red"],["#155eab",4,"blue"],["#86d64d",4,"green"]],"w":1000,"h":665,"by":"Gyula Jónás","alt":"Visible rgb pixels on a digital screen surface","cap":"RGB: a screen under a macro lens","src":"img/notes/c_dzjfnSneOxU.jpg"},{"screen":"Colour mixing: RGB, CMYK, hex codes and new colours","kind":"example","title":"CMYK: the four process inks","tag":"CMYK (subtractive)","html":"<p>Cyan, magenta, yellow and black (the K stands for \"key\") are the inks in every office printer and on the presses that print newspapers such as <i>The Daily Herald</i>. Printed dots of these inks <b>absorb</b> light, so the more ink you add, the darker the colour.</p><p>Because inks cannot reach every bright screen colour, an RGB design can look duller when printed. Convert to CMYK and check a proof before you print.</p>","q":null,"wide":false,"pal":[["#0a97d0",3,"cyan"],["#fa4e92",1,"pink-red"],["#f4d23e",4,"yellow-orange"],["#231a1d",5,"near black"]],"w":1000,"h":667,"by":"A J.","alt":"a row of different colored bottles sitting next to each other","cap":"CMYK: the four process inks","src":"img/notes/c_eVhc4EojmlY.jpg"},{"screen":"Colour psychology and meaning","kind":"example","title":"Red: chillies at a market","tag":"Red","html":"<p>Plates of red hot peppers: red is the colour of heat, energy and urgency. Your eye goes straight to it.</p><p>That is why red is used for sale banners, food brands and notification badges. Use it in small doses: a whole red page can feel aggressive or signal danger.</p>","q":null,"wide":false,"pal":[["#81100b",18,"dark red"],["#bc2018",8,"red"],["#9f8f79",17,"muted orange"]],"w":750,"h":1000,"by":"Jonathan Borba","alt":"Plates of red chili peppers displayed at a market","cap":"Red: chillies at a market","src":"img/notes/c_M7swW5Iy8cs.jpg"},{"screen":"Colour psychology and meaning","kind":"example","title":"Orange: fruit on a market stall","tag":"Orange","html":"<p>Piles of oranges feel fresh, friendly and affordable. Orange combines red's energy with yellow's cheerfulness, without red's sense of danger.</p><p>It is a popular colour for \"Order now\" and \"Join\" buttons and for youth and food brands.</p>","q":null,"wide":false,"pal":[["#bf6d04",36,"orange"],["#a74a03",20,"orange"],["#c5905a",2,"orange"]],"w":1000,"h":667,"by":"Georg Eiermann","alt":"orange fruits on white plastic container","cap":"Orange: fruit on a market stall","src":"img/notes/c___irSHvFyrg.jpg"},{"screen":"Colour psychology and meaning","kind":"example","title":"Yellow: a house in Aruba","tag":"Yellow","html":"<p>Sunshine yellow (<span class=\"hexchip\" style=\"--c:#C2B206\"><i></i>#C2B206</span>) under a blue sky: yellow says optimism, warmth and holiday. It is also the most visible colour, which is why it is used for warning signs.</p><p>On a screen, yellow text on white is almost unreadable. Use yellow as a background or highlight with dark text on top.</p>","q":null,"wide":false,"pal":[["#c2b206",68,"yellow"],["#44b0ea",6,"blue"],["#dfeff7",8,"near white"]],"w":800,"h":1000,"by":"Olivier Piquer","alt":"yellow painted house","cap":"Yellow: a house in Aruba","src":"img/notes/c_cjUfCXF201U.jpg"},{"screen":"Colour psychology and meaning","kind":"example","title":"Green: a banana plantation","tag":"Green","html":"<p>Green means nature, growth and health: think of banana and cocoa farms in St Lucia or Grenada. Health apps, eco-tourism sites and agricultural co-operatives often build their brands on greens like these.</p><p>Green also means \"go\" and \"success\" in interfaces, so it suits confirmation messages.</p>","q":null,"wide":false,"pal":[["#5a673c",29,"muted yellow-green"],["#3f462a",27,"dark muted yellow-green"],["#79895a",15,"muted yellow-green"],["#aca660",4,"yellow"]],"w":1000,"h":667,"by":"Jametlene Reskp","alt":"banana plant","cap":"Green: a banana plantation","src":"img/notes/c_R2vgo2Zm3Tc.jpg"},{"screen":"Colour psychology and meaning","kind":"example","title":"Blue: a boat on Caribbean-blue water","tag":"Blue","html":"<p>Clear turquoise and blue water (<span class=\"hexchip\" style=\"--c:#088DA7\"><i></i>#088DA7</span>, <span class=\"hexchip\" style=\"--c:#3CC1D6\"><i></i>#3CC1D6</span>) feels calm, clean and trustworthy. Blue is the most popular brand colour for banks, telecoms, airlines and social media.</p><p>In the Caribbean, blue also simply means <i>the sea</i>, so it is everywhere in tourism marketing.</p>","q":null,"wide":false,"pal":[["#088da7",42,"cyan"],["#3cc1d6",18,"cyan"],["#076882",18,"dark cyan"]],"w":1000,"h":750,"by":"Héctor Mavare","alt":"A boat travels across blue water","cap":"Blue: a boat on Caribbean-blue water","src":"img/notes/c_E0OVNeeCDBk.jpg"},{"screen":"Colour psychology and meaning","kind":"example","title":"Purple: a lavender-coloured flower","tag":"Purple","html":"<p>Purple has long been linked with royalty and luxury, because purple dye was once rare and expensive. Today it signals creativity, beauty and premium quality.</p><p>Notice the yellow centre: yellow is purple's complement, so nature has given this flower a built-in focal point.</p>","q":null,"wide":false,"pal":[["#a57fb8",25,"muted magenta"],["#d5c1e3",16,"light violet"],["#1f5103",20,"dark green"],["#ccaa08",9,"yellow-orange"]],"w":1000,"h":667,"by":"Ellephant","alt":"A close-up view of a beautiful lavender flower","cap":"Purple: a lavender-coloured flower","src":"img/notes/c_4XdiBT-O7lo.jpg"},{"screen":"Colour psychology and meaning","kind":"example","title":"Black and white: elegance in architecture","tag":"Black and white","html":"<p>With all hue removed, this curving building is pure line, shape and value. Black and white together feel elegant, modern and serious.</p><p>Luxury fashion and jewellery brands often use black and white so that the product, not the colour, gets the attention.</p>","q":null,"wide":false,"pal":[["#f2f2f2",37,"near white"],["#080808",34,"near black"],["#505050",11,"grey"]],"w":800,"h":1000,"by":"Joakim Nådell","alt":"The curved facade of Axel Towers in Copenhagen against a bright sky","cap":"Black and white: elegance in architecture","src":"img/notes/c_K67sBVqLLuw.jpg"},{"screen":"Colour psychology and meaning","kind":"example","title":"Culture: the Grenada flag painted on a tree","tag":"Cultural meaning","html":"<p>Red, gold and green carry deep meaning in the Caribbean. Grenada's flag uses them, and the same three colours are linked with the Pan-African movement and Rastafari, so they appear in Emancipation Day and reggae designs across the region.</p><p>A Japanese or Norwegian viewer might read the same colours very differently. Always ask what a colour means <b>to your audience</b>.</p>","q":"List three Caribbean flags. For each, give one colour and what it represents to the people of that country.","wide":true,"pal":[["#9a3545",5,"red"],["#e8ce5f",6,"yellow-orange"],["#05a58b",4,"teal"],["#0a0d0b",16,"near black"]],"w":905,"h":1000,"by":"Hugh Whyte","alt":"a flag painted on the bark of a tree","cap":"Culture: the Grenada flag painted on a tree","src":"img/notes/c_UmlSwpCmQXw.jpg"},{"screen":"Visual impact of colour combinations in digital formats","kind":"example","title":"High contrast: neon signs at night","tag":"High contrast","html":"<p>Bright neon reds, pinks and blues glowing against a dark room: maximum contrast in both hue and value. It grabs attention instantly and feels exciting, like a night out.</p><p>The same effect is used in dark-mode app designs and gaming sites. Too much of it, though, tires the eyes; use bright accents on a dark base, not everywhere.</p>","q":null,"wide":false,"pal":[["#511911",18,"dark red"],["#b02e24",12,"red"],["#c63f91",3,"pink-red"],["#ebb14a",2,"orange"],["#67bce3",1,"cyan"]],"w":750,"h":1000,"by":"Georgie Cobbs","alt":"multicolored lighted neon signs","cap":"High contrast: neon signs at night","src":"img/notes/c_SU35VU5de1o.jpg"},{"screen":"Visual impact of colour combinations in digital formats","kind":"example","title":"Low contrast: a foggy morning","tag":"Low contrast","html":"<p>Fog flattens everything into soft blue-greys (<span class=\"hexchip\" style=\"--c:#9394A0\"><i></i>#9394A0</span>, <span class=\"hexchip\" style=\"--c:#B8BCCD\"><i></i>#B8BCCD</span>). The mood is peaceful, but there is very little contrast between light and dark.</p><p>If you put grey text on a background like this it would fail accessibility checks. The WCAG guideline asks for a contrast ratio of at least 4.5:1 for normal body text; test your colours with a contrast checker.</p>","q":null,"wide":false,"pal":[["#9394a0",27,"grey"],["#b8bccd",22,"light muted blue"],["#2b384a",14,"dark muted blue"],["#d6d4d9",7,"off-white"]],"w":1000,"h":668,"by":"Steve Adams","alt":"a foggy lake with a boat in the foreground","cap":"Low contrast: a foggy morning","src":"img/notes/c_EJbNJpCfpvo.jpg"},{"screen":"Visual impact of colour combinations in digital formats","kind":"example","title":"The 60-30-10 rule in a living room","tag":"60-30-10","html":"<p>Look at the proportions: warm grey and beige furniture cover most of the scene, white curtains and walls make up most of the rest, and burnt-orange cushions (<span class=\"hexchip\" style=\"--c:#8F3805\"><i></i>#8F3805</span>, <span class=\"hexchip\" style=\"--c:#AF5C2B\"><i></i>#AF5C2B</span>) are a small accent.</p><p>That is the <b>60-30-10 rule</b>: about 60% dominant colour, 30% secondary and 10% accent. Website designers use the same split: background, surfaces and buttons.</p>","q":null,"wide":true,"pal":[["#a49b93",36,"grey"],["#e3e7eb",25,"light muted blue"],["#8f3805",3,"dark orange"],["#af5c2b",2,"orange"]],"w":592,"h":1000,"by":"Jetts Thanatip","alt":"A couch with orange pillows sits by a window","cap":"The 60-30-10 rule in a living room","src":"img/notes/c_jvv2e1NJc9s.jpg"},{"screen":"Designing a hero and a villain with colour","kind":"example","title":"Hero mood: a figure on a summit at sunrise","tag":"Hero","html":"<p>A lone figure stands on a peak against a golden dawn (<span class=\"hexchip\" style=\"--c:#E3D6AC\"><i></i>#E3D6AC</span>, <span class=\"hexchip\" style=\"--c:#CEAF6A\"><i></i>#CEAF6A</span>). Warm light, a rising sun and a clear sky say hope, courage and a new beginning: the classic hero palette.</p><p>Heroes are often designed with warm golds, clean whites and trustworthy blues, lit from the front or above.</p>","q":null,"wide":false,"pal":[["#e3d6ac",5,"light yellow-orange"],["#ceaf6a",5,"yellow-orange"],["#576b83",8,"muted blue"],["#0d0c07",41,"near black"]],"w":1000,"h":667,"by":"Andrés Mazariegos","alt":"A person stands on a mountain peak at sunrise","cap":"Hero mood: a figure on a summit at sunrise","src":"img/notes/c_vZd2R7h_jgY.jpg"},{"screen":"Designing a hero and a villain with colour","kind":"example","title":"Villain mood: a storm rolling in","tag":"Villain","html":"<p>Heavy, dark blue-grey clouds (<span class=\"hexchip\" style=\"--c:#313941\"><i></i>#313941</span>, <span class=\"hexchip\" style=\"--c:#464F5C\"><i></i>#464F5C</span>) press down over a lonely road. Low light and cold, desaturated colour create threat and tension.</p><p>Villains are often designed with dark shades, cold or sickly tones and harsh accent colours such as acid green or blood red, lit from below or from the side.</p>","q":null,"wide":false,"pal":[["#313941",15,"dark muted blue"],["#464f5c",36,"muted blue"],["#5c6675",18,"grey"],["#dcd1ca",9,"light muted orange"]],"w":750,"h":1000,"by":"Raychel Sanner","alt":"A paved road stretching toward the horizon under a heavy, dark storm sky","cap":"Villain mood: a storm rolling in","src":"img/notes/c_MnnXMvs4cQo.jpg"},{"screen":"Designing a hero and a villain with colour","kind":"example","title":"Warm light changes the mood","tag":"Warm light","html":"<p>Golden-hour sunlight wraps this face in deep reds and oranges. The same person photographed under a fluorescent light would look completely different.</p><p>When you design a hero, warm light makes them approachable and admirable.</p>","q":null,"wide":false,"pal":[["#661502",18,"dark red"],["#b76808",3,"orange"],["#eeba5e",1,"orange"],["#f8f4e7",17,"near white"]],"w":667,"h":1000,"by":"Zulfugar Karimov","alt":"A woman wearing glasses looking up into warm golden hour light","cap":"Warm light changes the mood","src":"img/notes/c_fmuBuRzRiko.jpg"},{"screen":"Designing a hero and a villain with colour","kind":"example","title":"Cool light changes the mood","tag":"Cool light","html":"<p>At blue hour the harbour turns cold and dark teal (<span class=\"hexchip\" style=\"--c:#29444B\"><i></i>#29444B</span>). Detail disappears into shadow: mysterious, lonely, slightly threatening.</p><p>Place a villain in scenes like this, then compare with the warm hero scene: colour alone tells the audience whom to trust.</p>","q":"Describe the palette you would use for a Caribbean folklore villain such as a jumbie or the soucouyant, and justify each colour.","wide":false,"pal":[["#29444b",22,"dark muted cyan"],["#06292e",42,"near black"]],"w":1000,"h":667,"by":"Christian Lue","alt":"A dark silhouette of a bridge over water with industrial cranes in the distance","cap":"Cool light changes the mood","src":"img/notes/c_fl4OL3Hqisw.jpg"}]};
/* Notes photographs and real-world colour examples.
   Every notes screen gets a captioned real photograph; colour theory and colour psychology screens also get
   in-depth "Real-world example" panels: a real photo, the palette measured from it (hex codes and share of the image)
   and an analysis linked to the notes. Images are stored inside the course. Kester Small. */
